/**
 * OpenRocket CSV Parser & Interpolator
 * Handles comments, metadata, flight events, and variable column layouts.
 */

class OpenRocketParser {
    constructor() {
        this.rawText = "";
        this.headers = [];
        this.colMap = {};
        this.records = [];
        this.events = [];
        this.delimiter = ",";
        this.meta = {
            title: "OpenRocket Simulation",
            pointsCount: 0,
            variablesCount: 0,
            duration: 0,
            maxAltitude: 0,
            maxVelocity: 0,
            maxAcceleration: 0,
            burnoutTime: 0,
            apogeeTime: 0,
            deployTime: 0,
            landingTime: 0
        };
    }

    /**
     * Detects delimiter from sample lines
     */
    detectDelimiter(csvText) {
        const lines = csvText.split(/\r?\n/).slice(0, 20);
        for (const line of lines) {
            const trimmed = line.trim();
            if (trimmed.toLowerCase().includes("time") || (!trimmed.startsWith("#") && trimmed.length > 5)) {
                const commas = (trimmed.match(/,/g) || []).length;
                const semicolons = (trimmed.match(/;/g) || []).length;
                const tabs = (trimmed.match(/\t/g) || []).length;
                if (semicolons > commas && semicolons > tabs) return ';';
                if (tabs > commas && tabs > semicolons) return '\t';
                return ',';
            }
        }
        return ',';
    }

    /**
     * Parses OpenRocket CSV string
     * @param {string} csvText
     * @returns {OpenRocketParser}
     */
    parse(csvText) {
        this.rawText = csvText;
        this.records = [];
        this.events = [];
        this.headers = [];
        this.colMap = {};
        this.delimiter = this.detectDelimiter(csvText);
        this.meta = {
            title: "OpenRocket Simulation",
            pointsCount: 0,
            variablesCount: 0,
            duration: 0,
            flightTime: 0,
            maxAltitude: 0,
            maxVelocity: 0,
            maxAcceleration: 0,
            burnoutTime: 0,
            apogeeTime: 0,
            deployTime: 0,
            landingTime: 0
        };

        const lines = csvText.split(/\r?\n/);
        let headerLine = null;

        for (let i = 0; i < lines.length; i++) {
            const line = lines[i].trim();
            if (!line) continue;

            const isComment = line.startsWith("#");
            const cleanLine = isComment ? line.substring(1).trim() : line;
            const lowerLine = cleanLine.toLowerCase();

            // Check for simulation title in initial comment
            if (isComment && i === 0 && !lowerLine.startsWith("time") && !lowerLine.startsWith("event")) {
                this.meta.title = cleanLine.replace(/[\(\[]?\s*up to date\s*[\)\]]?/gi, "").trim();
            }

            // Check for event comments: e.g. "# Event LIFTOFF occurred at t=0.126 seconds"
            if (isComment) {
                const eventMatch = cleanLine.match(/Event\s+([A-Za-z0-9_]+)\s+occurred\s+at\s+t\s*=\s*([0-9.]+)\s*seconds?/i);
                if (eventMatch) {
                    const eventName = eventMatch[1].toUpperCase();
                    const eventTime = parseFloat(eventMatch[2]);
                    this.events.push({
                        name: eventName,
                        time: eventTime,
                        label: this.formatEventLabel(eventName),
                        line: i
                    });
                }
            }

            // Check for header line: must contain the delimiter and "time" plus "alt" or "vel"
            if (!headerLine && cleanLine.includes(this.delimiter) && lowerLine.includes("time") && (lowerLine.includes("alt") || lowerLine.includes("vel") || lowerLine.includes("pos") || lowerLine.includes("speed"))) {
                headerLine = cleanLine;
                this.headers = this.splitCSVLine(cleanLine, this.delimiter).map(h => this.cleanHeader(h));
                this.buildColumnMap();
                continue;
            }

            // If header was not yet encountered, skip until header is found
            if (!headerLine) continue;

            // Skip any other comment lines
            if (isComment) continue;

            const values = this.splitCSVLine(line, this.delimiter);
            if (values.length < 2) continue;

            const record = this.extractRecord(values);
            if (record && !isNaN(record.time)) {
                this.records.push(record);
            }
        }

        // Sort records by time
        this.records.sort((a, b) => a.time - b.time);

        // Sort events by time
        this.events.sort((a, b) => a.time - b.time);

        // Calculate summary metrics
        this.calculateMetrics();

        return this;
    }

    /**
     * Splits CSV row respecting quotes and custom delimiter
     */
    splitCSVLine(line, delimiter = ",") {
        const result = [];
        let current = '';
        let inQuotes = false;

        for (let i = 0; i < line.length; i++) {
            const char = line[i];
            if (char === '"') {
                inQuotes = !inQuotes;
            } else if (char === delimiter && !inQuotes) {
                result.push(current.trim());
                current = '';
            } else {
                current += char;
            }
        }
        result.push(current.trim());
        return result;
    }

    /**
     * Cleans up header string and removes non-standard characters
     */
    cleanHeader(header) {
        return header
            .replace(/[^\x20-\x7E]+/g, '') // remove non-ascii
            .trim()
            .toLowerCase();
    }

    /**
     * Maps known variables to column indices
     */
    buildColumnMap() {
        this.colMap = {};
        this.headers.forEach((h, idx) => {
            // Elapsed simulation time (MUST NOT match computation time or time step)
            if (this.colMap.time === undefined) {
                if (h === "time" || h === "time (s)" || h === "# time (s)" || h === "t" || 
                   (h.startsWith("time") && !h.includes("step") && !h.includes("computation") && !h.includes("cpu"))) {
                    this.colMap.time = idx;
                }
            }

            // Altitude (MUST NOT match altitude above sea level)
            if (this.colMap.alt === undefined) {
                if (h === "altitude" || h === "altitude (m)" || h === "alt" || 
                   (h.startsWith("altitude") && !h.includes("sea") && !h.includes("asl"))) {
                    this.colMap.alt = idx;
                }
            }

            if (h.includes("altitude above sea level") || h.includes("alt asl")) this.colMap.altASL = idx;
            else if (h.includes("vertical velocity") || h === "vert vel" || h === "vz") this.colMap.vertVel = idx;
            else if (h.includes("total velocity") || (h.includes("velocity") && !h.includes("vertical") && !h.includes("lateral") && !h.includes("wind")) || h === "speed") this.colMap.totalVel = idx;
            else if (h.includes("vertical acceleration") || h === "vert acc") this.colMap.vertAcc = idx;
            else if (h.includes("total acceleration") || (h.includes("acceleration") && !h.includes("vertical") && !h.includes("lateral") && !h.includes("coriolis") && !h.includes("gravitational"))) this.colMap.totalAcc = idx;
            else if (h.includes("position east") || h.includes("east of launch") || h.includes("pos x") || h === "x") this.colMap.posX = idx;
            else if (h.includes("position north") || h.includes("north of launch") || h.includes("pos z") || h.includes("pos y") || h === "y" || h === "z") this.colMap.posZ = idx;
            else if (h.includes("lateral distance")) this.colMap.lateralDist = idx;
            else if (h.includes("lateral direction")) this.colMap.lateralDir = idx;
            else if (h.includes("lateral velocity")) this.colMap.lateralVel = idx;
            else if (h.includes("lateral acceleration")) this.colMap.lateralAcc = idx;
            else if (this.colMap.aoa === undefined && (h.includes("angle of attack") || h.includes("aoa"))) this.colMap.aoa = idx;
            else if (this.colMap.zenith === undefined && (h.includes("vertical orientation") || h.includes("zenith") || h === "pitch" || (h.startsWith("pitch") && !h.includes("rate") && !h.includes("moment") && !h.includes("damping")))) this.colMap.zenith = idx;
            else if (this.colMap.azimuth === undefined && (h.includes("lateral orientation") || h.includes("azimuth") || h === "yaw" || h === "heading" || (h.startsWith("yaw") && !h.includes("rate") && !h.includes("moment") && !h.includes("damping")))) this.colMap.azimuth = idx;
            else if (h.includes("motor mass")) this.colMap.motorMass = idx;
            else if (h.startsWith("mass")) this.colMap.mass = idx;
            else if (h.startsWith("thrust") && !h.includes("ratio") && !h.includes("weight")) this.colMap.thrust = idx;
            else if (h.includes("thrust-to-weight") || h.includes("twr")) this.colMap.twr = idx;
            else if (h.startsWith("drag force") || h === "drag") this.colMap.drag = idx;
            else if (h.includes("mach")) this.colMap.mach = idx;
            else if (h.includes("wind velocity") || h.includes("wind speed")) this.colMap.windVel = idx;
            else if (h.includes("wind direction")) this.colMap.windDir = idx;
        });

        // Smart fallbacks
        if (this.colMap.time === undefined) this.colMap.time = 0;
        if (this.colMap.alt === undefined) {
            const altIdx = this.headers.findIndex(h => h.includes("alt") || h.includes("height"));
            this.colMap.alt = altIdx !== -1 ? altIdx : 1;
        }
    }

    /**
     * Extracts and normalizes record object from tokens
     */
    extractRecord(values) {
        const getNum = (key, defaultVal = 0) => {
            const idx = this.colMap[key];
            if (idx === undefined || idx >= values.length) return defaultVal;
            let raw = values[idx].trim();
            // Handle European decimal comma if delimiter is semicolon
            if (this.delimiter === ';' && raw.includes(',')) {
                raw = raw.replace(',', '.');
            }
            const val = parseFloat(raw);
            return isNaN(val) ? defaultVal : val;
        };

        const time = getNum("time");
        const alt = getNum("alt");
        const posX = getNum("posX", 0); // East
        const posZ = getNum("posZ", 0); // North
        const vertVel = getNum("vertVel");
        const totalVel = getNum("totalVel", Math.abs(vertVel));
        const vertAcc = getNum("vertAcc");
        const totalAcc = getNum("totalAcc", Math.abs(vertAcc));
        const thrust = getNum("thrust");
        const drag = getNum("drag");
        const zenith = getNum("zenith", 85);
        const azimuth = getNum("azimuth", 90);
        const lateralDist = getNum("lateralDist", Math.hypot(posX, posZ));
        const mass = getNum("mass");
        const mach = getNum("mach");
        const windVel = getNum("windVel");

        return {
            time,
            alt,
            posX,
            posZ,
            vertVel,
            totalVel,
            vertAcc,
            totalAcc,
            thrust,
            drag,
            zenith,
            azimuth,
            lateralDist,
            mass,
            mach,
            windVel
        };
    }

    /**
     * Computes high-level flight stats
     */
    calculateMetrics() {
        if (this.records.length === 0) return;

        let maxAlt = 0;
        let maxVel = 0;
        let maxAcc = 0;
        let apogeeTime = 0;

        for (const r of this.records) {
            if (r.alt > maxAlt) {
                maxAlt = r.alt;
                apogeeTime = r.time;
            }
            if (r.totalVel > maxVel) maxVel = r.totalVel;
            if (r.totalAcc > maxAcc) maxAcc = r.totalAcc;
        }

        this.meta.duration = this.records[this.records.length - 1].time;
        this.meta.flightTime = this.meta.duration;
        this.meta.pointsCount = this.records.length;
        this.meta.maxAltitude = maxAlt;
        this.meta.maxVelocity = maxVel;
        this.meta.maxAcceleration = maxAcc;
        this.meta.apogeeTime = apogeeTime;

        // Find standard event times
        for (const ev of this.events) {
            if (ev.name.includes("BURNOUT")) this.meta.burnoutTime = ev.time;
            if (ev.name.includes("APOGEE")) this.meta.apogeeTime = ev.time;
            if (ev.name.includes("GROUND") || ev.name.includes("LANDING") || ev.name.includes("HIT")) {
                this.meta.landingTime = ev.time;
            }
        }

        if (this.meta.landingTime) {
            this.meta.flightTime = this.meta.landingTime;
        }

        // Parachute deployment: prioritize physical deployment/recovery device event over ejection charge
        const deployEv = this.events.find(e => e.name.includes("RECOVERY") || e.name.includes("DEPLOYMENT") || e.name.includes("PARACHUTE"));
        const ejectionEv = this.events.find(e => e.name.includes("EJECTION"));
        if (deployEv) {
            this.meta.deployTime = deployEv.time;
        } else if (ejectionEv) {
            this.meta.deployTime = ejectionEv.time;
        } else {
            this.meta.deployTime = this.meta.apogeeTime;
        }

        // Fallbacks
        if (!this.meta.burnoutTime) {
            let lastThrustRecord = null;
            for (const r of this.records) {
                if (r.thrust > 0.1) lastThrustRecord = r;
            }
            if (lastThrustRecord) this.meta.burnoutTime = lastThrustRecord.time;
        }

        if (!this.meta.deployTime) {
            // Default deploy near apogee if not explicitly marked
            this.meta.deployTime = this.meta.apogeeTime || 4.65;
        }
    }

    /**
     * Interpolates flight state at any given timestamp t
     * @param {number} t Time in seconds
     */
    sample(t) {
        if (this.records.length === 0) return null;

        if (t <= this.records[0].time) return this.records[0];
        if (t >= this.records[this.records.length - 1].time) {
            return this.records[this.records.length - 1];
        }

        let low = 0;
        let high = this.records.length - 1;
        while (low <= high) {
            const mid = (low + high) >> 1;
            if (this.records[mid].time < t) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        const r0 = this.records[low - 1];
        const r1 = this.records[low];
        if (!r1) return r0;

        const factor = (t - r0.time) / (r1.time - r0.time);
        const lerp = (a, b) => a + (b - a) * factor;

        return {
            time: t,
            alt: lerp(r0.alt, r1.alt),
            posX: lerp(r0.posX, r1.posX),
            posZ: lerp(r0.posZ, r1.posZ),
            vertVel: lerp(r0.vertVel, r1.vertVel),
            totalVel: lerp(r0.totalVel, r1.totalVel),
            vertAcc: lerp(r0.vertAcc, r1.vertAcc),
            totalAcc: lerp(r0.totalAcc, r1.totalAcc),
            thrust: lerp(r0.thrust, r1.thrust),
            drag: lerp(r0.drag, r1.drag),
            zenith: lerp(r0.zenith, r1.zenith),
            azimuth: lerp(r0.azimuth, r1.azimuth),
            lateralDist: lerp(r0.lateralDist, r1.lateralDist),
            mass: lerp(r0.mass, r1.mass),
            mach: lerp(r0.mach, r1.mach),
            windVel: lerp(r0.windVel, r1.windVel)
        };
    }

    /**
     * Determines current flight phase at time t
     */
    getFlightPhase(t) {
        if (t <= 0) return { name: "Pad Ready", color: "#64748b" };
        
        const liftoffEvent = this.events.find(e => e.name === "LIFTOFF");
        const liftoffTime = liftoffEvent ? liftoffEvent.time : 0.1;
        
        if (t < liftoffTime) return { name: "Ignition", color: "#f59e0b" };
        if (t <= (this.meta.burnoutTime || 1.65)) return { name: "Boost", color: "#ef4444" };
        if (t < (this.meta.deployTime || this.meta.apogeeTime || 4.65)) return { name: "Coasting", color: "#38bdf8" };
        if (t < (this.meta.landingTime || this.meta.duration)) return { name: "Recovery", color: "#10b981" };
        return { name: "Touchdown", color: "#8b5cf6" };
    }

    /**
     * Formats event name into a readable title
     */
    formatEventLabel(name) {
        const map = {
            "IGNITION": "Ignition",
            "LAUNCH": "Launch Command",
            "LIFTOFF": "Liftoff",
            "LAUNCHROD": "Launch Rod Clear",
            "BURNOUT": "Motor Burnout",
            "EJECTION_CHARGE": "Ejection Charge",
            "RECOVERY_DEVICE_DEPLOYMENT": "Parachute Deployed",
            "APOGEE": "Apogee Peak",
            "GROUND_HIT": "Ground Touchdown",
            "SIMULATION_END": "Simulation End"
        };
        return map[name] || name.replace(/_/g, " ");
    }

    /**
     * Derives a clean engineering simulation title
     */
    getCleanTitle(fileName = "") {
        let raw = (this.meta.title || "").trim();
        // Remove "(Up to date)" or "[Up to date]" or loose "up to date"
        raw = raw.replace(/[\(\[]?\s*up to date\s*[\)\]]?/gi, "").trim();
        raw = raw.replace(/\s{2,}/g, " ").trim();

        if (raw && !raw.toLowerCase().includes("simulation")) {
            const motorMatch = raw.match(/^([A-Za-z0-9\-]+)(?:\s+Motor)?(?:\s+Altitude.*|\s+vs\s+Time.*)?$/i);
            if (motorMatch && motorMatch[1]) {
                return `${motorMatch[1]} Flight Simulation`;
            }
            raw = raw.replace(/\s+Altitude(?:\/Lateral)?\s+vs\s+Time/i, " Flight Simulation");
            if (!raw.toLowerCase().includes("simulation")) {
                raw += " Flight Simulation";
            }
            return raw;
        }

        if (raw) return raw;

        if (fileName) {
            const base = fileName.replace(/\.[^/.]+$/, "");
            return `${base} Flight Simulation`;
        }

        return "OpenRocket Flight Simulation";
    }
}


/**
 * OpenRocket 3D Visualizer
 * Three.js WebGL rendering engine with procedural rocket, launch pad,
 * dynamic parachute, particle exhaust, trajectory ribbon, and multiple camera modes.
 */

class RocketVisualizer {
    constructor(containerElement) {
        this.container = containerElement;
        this.scene = null;
        this.camera = null;
        this.renderer = null;
        this.controls = null;

        // Visual elements
        this.rocketGroup = null;
        this.rocketBeacon = null;
        this.parachuteGroup = null;
        this.exhaustLight = null;
        this.flameMesh = null;
        this.launchPadGroup = null;
        this.trajectoryGroup = null;
        this.landingMarker = null;

        // Ground projection & Altitude shadow
        this.groundProjectionGroup = null;
        this.groundShadowMesh = null;
        this.groundReticle = null;
        this.altitudePlumbLine = null;

        // Satellite ground & environment
        this.satelliteGroundMesh = null;
        this.peripheralGroundMesh = null;
        this.darkGroundMesh = null;
        this.telemetryGridGroup = null;
        this.isSatelliteMap = true;
        this.activeLaunchField = 'parallel'; // Default: Soccer field parallel with parking lot

        // Particle systems
        this.particles = [];
        this.particlePool = [];

        // Camera settings
        this.cameraMode = "chase"; // 'chase', 'pad', 'free', 'apogee'
        this.chaseDistance = 6.5;
        this.lastRocketPos = null;
        this.chaseOffset = new THREE.Vector3(-3.5, 2.2, 5.5);
        this.cameraLerpSpeed = 0.08;
        this.billboardBadges = [];

        // Flight data
        this.flightData = null;
        this.isLoaded = false;

        this.init();
    }

    init() {
        const width = this.container.clientWidth;
        const height = this.container.clientHeight;

        // Scene with subtle atmospheric depth gradient (near terrain -> distant terrain -> horizon -> sky)
        this.scene = new THREE.Scene();
        const skyAtmosphereColor = new THREE.Color(0x0c1322);
        this.scene.background = skyAtmosphereColor;
        this.scene.fog = new THREE.Fog(0x0c1322, 160, 950);

        // Camera
        this.camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 2000);
        this.camera.position.set(15, 10, 20);

        // Renderer
        this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
        this.renderer.setSize(width, height);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        this.renderer.shadowMap.enabled = true;
        this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
        this.renderer.toneMappingExposure = 1.1;
        this.container.appendChild(this.renderer.domElement);

        // OrbitControls
        this.controls = new THREE.OrbitControls(this.camera, this.renderer.domElement);
        this.controls.enableDamping = true;
        this.controls.dampingFactor = 0.05;
        this.controls.maxPolarAngle = Math.PI / 2 + 0.05; // Don't go below ground
        this.controls.minDistance = 1.0;
        this.controls.maxDistance = 1500;

        // Lighting
        this.setupLighting();

        // Environment & Ground
        this.setupEnvironment();

        // Rocket Model
        this.setupRocketModel();

        // Real-Time Ground Projection & Altitude Shadow
        this.setupGroundProjection();

        // Trajectory Group
        this.trajectoryGroup = new THREE.Group();
        this.scene.add(this.trajectoryGroup);

        // Initial Chase Cam position behind pad framing the rocket and launch field
        const initOffset = new THREE.Vector3(-4.5, 1.8, 5.0);
        this.camera.position.set(initOffset.x, 0.6 + initOffset.y, initOffset.z);
        this.controls.target.set(0, 0.6, 0);
        this.lastRocketPos = new THREE.Vector3(0, 0.6, 0);
        this.controls.update();

        // Handle resize
        window.addEventListener("resize", () => this.onWindowResize());
    }

    setupLighting() {
        // Ambient sky light - natural Arizona daylight with subtle ground bounce
        const hemiLight = new THREE.HemisphereLight(0xdbeafe, 0x1e2e1e, 0.7);
        hemiLight.position.set(0, 200, 0);
        this.scene.add(hemiLight);

        // Directional Sun with refined shadow frustum covering flight volume
        const sunLight = new THREE.DirectionalLight(0xfff8ee, 1.4);
        sunLight.position.set(120, 250, 100);
        sunLight.castShadow = true;
        sunLight.shadow.mapSize.width = 2048;
        sunLight.shadow.mapSize.height = 2048;
        sunLight.shadow.camera.near = 0.5;
        sunLight.shadow.camera.far = 700;
        const d = 100;
        sunLight.shadow.camera.left = -d;
        sunLight.shadow.camera.right = d;
        sunLight.shadow.camera.top = d;
        sunLight.shadow.camera.bottom = -d;
        sunLight.shadow.bias = -0.0003;
        this.scene.add(sunLight);

        // Secondary sky fill light
        const fillLight = new THREE.DirectionalLight(0x7dd3fc, 0.35);
        fillLight.position.set(-80, 100, -80);
        this.scene.add(fillLight);

        // Subtle edge / rim light for realistic rocket silhouette separation
        const rimLight = new THREE.DirectionalLight(0x38bdf8, 0.45);
        rimLight.position.set(-60, 45, -120);
        this.scene.add(rimLight);
    }

    setupEnvironment() {
        // Telemetry Grid & Range Rings Group
        this.telemetryGridGroup = new THREE.Group();

        // Coordinate Grid
        const gridHelper = new THREE.GridHelper(300, 60, 0x475569, 0x1e293b);
        gridHelper.position.y = 0.04;
        if (gridHelper.material) {
            gridHelper.material.depthWrite = false;
            gridHelper.material.transparent = true;
            gridHelper.material.opacity = 0.28;
        }
        this.telemetryGridGroup.add(gridHelper);

        // Distance range rings (10m, 25m, 50m, 100m, 150m)
        const rings = [10, 25, 50, 100, 150];
        rings.forEach(radius => {
            const ringGeo = new THREE.RingGeometry(radius - 0.15, radius + 0.15, 64);
            const ringMat = new THREE.MeshBasicMaterial({
                color: 0x64748b,
                side: THREE.DoubleSide,
                transparent: true,
                opacity: 0.28,
                depthWrite: false
            });
            const ring = new THREE.Mesh(ringGeo, ringMat);
            ring.rotation.x = -Math.PI / 2;
            ring.position.y = 0.05;
            this.telemetryGridGroup.add(ring);
        });

        // Cardinal direction markers
        this.createCardinalLabels(this.telemetryGridGroup);
        this.scene.add(this.telemetryGridGroup);

        // 1. Extended peripheral ground skirt (natural Arizona park lawn/desert tone blending with horizon)
        const periGeo = new THREE.PlaneGeometry(2500, 2500);
        const periMat = new THREE.MeshStandardMaterial({
            color: 0x141f17,
            roughness: 0.95,
            metalness: 0.05
        });
        this.peripheralGroundMesh = new THREE.Mesh(periGeo, periMat);
        this.peripheralGroundMesh.rotation.x = -Math.PI / 2;
        this.peripheralGroundMesh.position.y = -0.15;
        this.peripheralGroundMesh.receiveShadow = true;
        this.scene.add(this.peripheralGroundMesh);

        // 2. High-Resolution Freestone Park Satellite Ground Mesh
        // 4095 x 4095 composite @ 0.12471 m/px = 510.69m x 510.69m
        const satGeo = new THREE.PlaneGeometry(510.69, 510.69);
        const satMat = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            roughness: 0.85,
            metalness: 0.05
        });
        this.satelliteGroundMesh = new THREE.Mesh(satGeo, satMat);
        this.satelliteGroundMesh.rotation.x = -Math.PI / 2;
        this.satelliteGroundMesh.position.y = 0.0;
        this.satelliteGroundMesh.receiveShadow = true;

        // Default: Soccer Field parallel with parking lot (centered on kickoff spot at mosaic origin)
        this.setLaunchField('parallel');
        this.scene.add(this.satelliteGroundMesh);

        // 3. Fallback Dark Sci-Fi Ground Plane
        const darkGeo = new THREE.PlaneGeometry(2500, 2500);
        const darkMat = new THREE.MeshStandardMaterial({
            color: 0x0f172a,
            roughness: 0.9,
            metalness: 0.1
        });
        this.darkGroundMesh = new THREE.Mesh(darkGeo, darkMat);
        this.darkGroundMesh.rotation.x = -Math.PI / 2;
        this.darkGroundMesh.position.y = -0.04;
        this.darkGroundMesh.receiveShadow = true;
        this.darkGroundMesh.visible = false;
        this.scene.add(this.darkGroundMesh);

        // Load Satellite Texture
        this.loadSatelliteTexture();

        // Launch Pad Base & Rod
        this.setupLaunchPad();
    }

    loadSatelliteTexture() {
        const loader = new THREE.TextureLoader();
        const textureSrc = (typeof window !== 'undefined' && window.FREESTONE_SATELLITE_DATA)
            ? window.FREESTONE_SATELLITE_DATA
            : 'data/freestone_stitched_2k.jpg';

        const applyTex = (texture) => {
            if (this.renderer && this.renderer.capabilities) {
                texture.anisotropy = Math.min(8, this.renderer.capabilities.getMaxAnisotropy() || 1);
            }
            texture.generateMipmaps = true;
            if ('sRGBEncoding' in THREE) {
                texture.encoding = THREE.sRGBEncoding;
            }
            if (this.satelliteGroundMesh) {
                this.satelliteGroundMesh.material.map = texture;
                this.satelliteGroundMesh.material.needsUpdate = true;
            }
        };

        loader.load(textureSrc, applyTex, undefined, () => {
            loader.load('data/freestone_stitched_2k.jpg', applyTex, undefined, (e) => {
                console.warn('Satellite texture load fallback:', e);
            });
        });
    }

    setLaunchField(fieldId) {
        this.activeLaunchField = fieldId;
        if (!this.satelliteGroundMesh) return;

        if (fieldId === 'west' || fieldId === 'perp' || fieldId === 'field1') {
            // Perpendicular West soccer field (X=1165, Y=1836 in 4K composite)
            // Offset from image center: dx = -110.06m (West), dy = -26.38m (North)
            this.satelliteGroundMesh.position.x = 110.06;
            this.satelliteGroundMesh.position.z = 26.38;
        } else {
            // Default: Soccer field parallel with the curved parking lot
            // Kickoff spot is at (2048, 2048) - the exact junction of the 4 satellite quadrants!
            // Ground mesh (510.69m x 510.69m) centered at (0, 0) places pad directly on the kickoff spot
            this.satelliteGroundMesh.position.x = 0.0;
            this.satelliteGroundMesh.position.z = 0.0;
        }
    }

    setSatelliteMap(enabled) {
        this.isSatelliteMap = enabled;
        if (this.satelliteGroundMesh) this.satelliteGroundMesh.visible = enabled;
        if (this.peripheralGroundMesh) this.peripheralGroundMesh.visible = enabled;
        if (this.darkGroundMesh) this.darkGroundMesh.visible = !enabled;
    }

    setGridVisible(enabled) {
        if (this.telemetryGridGroup) this.telemetryGridGroup.visible = enabled;
    }

    createCardinalLabels(targetGroup) {
        const group = targetGroup || this.scene;
        const createLabel = (text, pos) => {
            const canvas = document.createElement('canvas');
            canvas.width = 128;
            canvas.height = 128;
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = '#38bdf8';
            ctx.font = 'Bold 48px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(text, 64, 64);

            const texture = new THREE.CanvasTexture(canvas);
            const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true, opacity: 0.75 });
            const sprite = new THREE.Sprite(spriteMat);
            sprite.position.copy(pos);
            sprite.scale.set(6, 6, 1);
            group.add(sprite);
        };

        createLabel("N", new THREE.Vector3(0, 1.5, -45));
        createLabel("S", new THREE.Vector3(0, 1.5, 45));
        createLabel("E", new THREE.Vector3(45, 1.5, 0));
        createLabel("W", new THREE.Vector3(-45, 1.5, 0));
    }

    setupLaunchPad() {
        this.launchPadGroup = new THREE.Group();

        // Triangular Pad Legs
        const legMat = new THREE.MeshStandardMaterial({ color: 0x475569, metalness: 0.8, roughness: 0.3 });
        for (let i = 0; i < 3; i++) {
            const angle = (i * Math.PI * 2) / 3;
            const legGeo = new THREE.CylinderGeometry(0.04, 0.04, 1.2, 8);
            const leg = new THREE.Mesh(legGeo, legMat);
            leg.position.set(Math.cos(angle) * 0.45, 0.3, Math.sin(angle) * 0.45);
            leg.rotation.z = Math.sin(angle) * 0.4;
            leg.rotation.x = -Math.cos(angle) * 0.4;
            leg.castShadow = true;
            this.launchPadGroup.add(leg);
        }

        // Pad Hub plate
        const hubGeo = new THREE.CylinderGeometry(0.35, 0.4, 0.1, 16);
        const hubMat = new THREE.MeshStandardMaterial({ color: 0xe2e8f0, metalness: 0.7, roughness: 0.2 });
        const hub = new THREE.Mesh(hubGeo, hubMat);
        hub.position.y = 0.55;
        hub.castShadow = true;
        this.launchPadGroup.add(hub);

        // Blast Deflector
        const deflectorGeo = new THREE.ConeGeometry(0.3, 0.25, 16);
        const deflectorMat = new THREE.MeshStandardMaterial({ color: 0x334155, metalness: 0.9, roughness: 0.4 });
        const deflector = new THREE.Mesh(deflectorGeo, deflectorMat);
        deflector.position.y = 0.65;
        this.launchPadGroup.add(deflector);

        // Launch Rod (1.2m rod, tilted matching launch zenith/azimuth)
        const rodGeo = new THREE.CylinderGeometry(0.015, 0.015, 1.3, 8);
        const rodMat = new THREE.MeshStandardMaterial({ color: 0x94a3b8, metalness: 0.95, roughness: 0.1 });
        const rod = new THREE.Mesh(rodGeo, rodMat);
        rod.position.y = 1.2;
        rod.castShadow = true;
        this.launchPadGroup.add(rod);

        this.scene.add(this.launchPadGroup);
    }

    setupRocketModel() {
        this.rocketGroup = new THREE.Group();

        // Body tube (scale normalized: height ~1.2m, diameter ~0.08m for high visibility)
        const bodyLength = 0.8;
        const bodyRadius = 0.045;
        const bodyGeo = new THREE.CylinderGeometry(bodyRadius, bodyRadius, bodyLength, 32);
        const BodyMatClass = THREE.MeshPhysicalMaterial || THREE.MeshStandardMaterial;

        // White semi-gloss aerospace body
        const bodyMat = new BodyMatClass({
            color: 0xf8fafc,
            roughness: 0.22,
            metalness: 0.1,
            clearcoat: 0.35,
            clearcoatRoughness: 0.22
        });
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.position.y = bodyLength / 2;
        body.castShadow = true;
        this.rocketGroup.add(body);

        // Colored stripe decal
        const stripeGeo = new THREE.CylinderGeometry(bodyRadius + 0.001, bodyRadius + 0.001, 0.1, 32);
        const stripeMat = new BodyMatClass({
            color: 0xef4444,
            roughness: 0.25,
            metalness: 0.1,
            clearcoat: 0.3,
            clearcoatRoughness: 0.25
        });
        const stripe = new THREE.Mesh(stripeGeo, stripeMat);
        stripe.position.y = bodyLength * 0.75;
        this.rocketGroup.add(stripe);

        // Nosecone (Ogive tangent curve with clean specular highlight)
        const noseLength = 0.3;
        const noseGeo = new THREE.ConeGeometry(bodyRadius, noseLength, 32);
        const noseMat = new BodyMatClass({
            color: 0xdc2626, // Bright rocket red
            roughness: 0.18,
            metalness: 0.15,
            clearcoat: 0.45,
            clearcoatRoughness: 0.18
        });
        const nose = new THREE.Mesh(noseGeo, noseMat);
        nose.position.y = bodyLength + (noseLength / 2);
        nose.castShadow = true;
        this.rocketGroup.add(nose);

        // Engine Nozzle
        const nozzleGeo = new THREE.CylinderGeometry(bodyRadius * 0.6, bodyRadius * 0.75, 0.08, 16);
        const nozzleMat = new THREE.MeshStandardMaterial({ color: 0x1e293b, metalness: 0.9, roughness: 0.45 });
        const nozzle = new THREE.Mesh(nozzleGeo, nozzleMat);
        nozzle.position.y = -0.04;
        this.rocketGroup.add(nozzle);

        // 4 Swept Fins (carbon-graphite matte finish)
        const finShape = new THREE.Shape();
        finShape.moveTo(0, 0);
        finShape.lineTo(0.14, -0.08);
        finShape.lineTo(0.12, 0.08);
        finShape.lineTo(0, 0.18);
        finShape.closePath();

        const extrudeSettings = { depth: 0.006, bevelEnabled: true, bevelSegments: 2, steps: 1, bevelSize: 0.002, bevelThickness: 0.002 };
        const finGeo = new THREE.ExtrudeGeometry(finShape, extrudeSettings);
        const finMat = new THREE.MeshStandardMaterial({ color: 0x1e293b, roughness: 0.35, metalness: 0.4 });

        for (let i = 0; i < 4; i++) {
            const fin = new THREE.Mesh(finGeo, finMat);
            fin.rotation.y = (i * Math.PI) / 2;
            fin.position.y = 0.05;
            fin.castShadow = true;
            this.rocketGroup.add(fin);
        }

        // High-Contrast Rocket Tracking Reticle / Beacon (distance-faded)
        this.rocketBeacon = new THREE.Group();
        const beaconGeo = new THREE.RingGeometry(0.68, 0.76, 36);
        this.rocketBeaconMat = new THREE.MeshBasicMaterial({
            color: 0xfbbf24,
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.0,
            depthWrite: false
        });
        const beaconRing = new THREE.Mesh(beaconGeo, this.rocketBeaconMat);
        this.rocketBeacon.add(beaconRing);

        // 4 crosshair ticks
        const bTickPts = [
            new THREE.Vector3(0, 0.76, 0), new THREE.Vector3(0, 0.95, 0),
            new THREE.Vector3(0, -0.76, 0), new THREE.Vector3(0, -0.95, 0),
            new THREE.Vector3(0.76, 0, 0), new THREE.Vector3(0.95, 0, 0),
            new THREE.Vector3(-0.76, 0, 0), new THREE.Vector3(-0.95, 0, 0)
        ];
        const bTickGeo = new THREE.BufferGeometry().setFromPoints(bTickPts);
        this.rocketBeaconTickMat = new THREE.LineBasicMaterial({
            color: 0xfbbf24,
            transparent: true,
            opacity: 0.0,
            depthWrite: false
        });
        const bTicks = new THREE.LineSegments(bTickGeo, this.rocketBeaconTickMat);
        this.rocketBeacon.add(bTicks);

        this.rocketBeacon.material = this.rocketBeaconMat;
        this.rocketBeacon.position.y = bodyLength * 0.5;
        this.rocketGroup.add(this.rocketBeacon);

        // Exhaust flame mesh (animated when thrusting)
        const flameGeo = new THREE.ConeGeometry(bodyRadius * 0.7, 0.5, 16);
        flameGeo.rotateX(Math.PI); // point downwards
        flameGeo.translate(0, -0.3, 0);
        const flameMat = new THREE.MeshBasicMaterial({
            color: 0xff6600,
            transparent: true,
            opacity: 0.85
        });
        this.flameMesh = new THREE.Mesh(flameGeo, flameMat);
        this.flameMesh.visible = false;
        this.rocketGroup.add(this.flameMesh);

        // Exhaust PointLight
        this.exhaustLight = new THREE.PointLight(0xff7700, 0, 8);
        this.exhaustLight.position.set(0, -0.2, 0);
        this.rocketGroup.add(this.exhaustLight);

        // Parachute Group (attached above rocket)
        this.setupParachute();

        // Initial position resting on pad
        this.rocketGroup.position.set(0, 0.6, 0);
        this.scene.add(this.rocketGroup);
    }

    setupParachute() {
        this.parachuteGroup = new THREE.Group();

        // Rocket nose tip anchor: bodyLength (0.8) + noseLength (0.3) = 1.1m
        const noseTipY = 1.1;
        this.parachuteGroup.position.set(0, noseTipY, 0);

        // 1. Recovery Line (Shock Cord from nosecone tip to suspension line confluence point)
        const swivelY = 0.35; // 0.35m above nose tip
        const shockLineGeo = new THREE.BufferGeometry().setFromPoints([
            new THREE.Vector3(0, 0, 0),
            new THREE.Vector3(0, swivelY, 0)
        ]);
        const shockLineMat = new THREE.LineBasicMaterial({ color: 0xf1f5f9 });
        const shockLine = new THREE.Line(shockLineGeo, shockLineMat);
        this.parachuteGroup.add(shockLine);

        // Swivel eyelet ring at line confluence point
        const swivelGeo = new THREE.TorusGeometry(0.016, 0.004, 8, 16);
        const swivelMat = new THREE.MeshStandardMaterial({ color: 0xfbbf24, metalness: 0.8, roughness: 0.3 });
        const swivel = new THREE.Mesh(swivelGeo, swivelMat);
        swivel.position.set(0, swivelY, 0);
        swivel.rotation.x = Math.PI / 2;
        this.parachuteGroup.add(swivel);

        // 2. Parachute Canopy (Hemisphere: apex UP, open skirt rim facing DOWN)
        const canopyRadius = 0.5;
        const canopySkirtY = 1.1; // Skirt rim 1.1m above nose tip
        const canopyGeo = new THREE.SphereGeometry(canopyRadius, 32, 20, 0, Math.PI * 2, 0, Math.PI / 2);

        // Striped two-tone texture (12 vertical gores mapping to sphere UVs)
        const canvas = document.createElement('canvas');
        canvas.width = 512;
        canvas.height = 256;
        const ctx = canvas.getContext('2d');
        const numGores = 12;
        const goreWidth = 512 / numGores;
        for (let i = 0; i < numGores; i++) {
            ctx.fillStyle = (i % 2 === 0) ? '#ff5500' : '#ffffff';
            ctx.fillRect(i * goreWidth, 0, goreWidth, 256);
            ctx.fillStyle = 'rgba(0, 0, 0, 0.07)';
            ctx.fillRect(i * goreWidth, 0, 2, 256);
            ctx.fillRect((i + 1) * goreWidth - 2, 0, 2, 256);
        }
        const canopyTexture = new THREE.CanvasTexture(canvas);

        const canopyMat = new THREE.MeshStandardMaterial({
            map: canopyTexture,
            side: THREE.DoubleSide,
            roughness: 0.6,
            metalness: 0.05
        });

        const canopy = new THREE.Mesh(canopyGeo, canopyMat);
        // Default SphereGeometry: apex is at +Y, open rim is at Y=0.
        // No rotation around X: opening already faces downwards toward the rocket.
        canopy.position.set(0, canopySkirtY, 0);
        this.parachuteGroup.add(canopy);

        // 3. 12 Suspension Lines connecting canopy skirt rim down to swivel eyelet
        const lineMat = new THREE.LineBasicMaterial({ color: 0xe2e8f0, transparent: true, opacity: 0.75 });
        for (let i = 0; i < numGores; i++) {
            const angle = (i * Math.PI * 2) / numGores;
            const rimX = Math.cos(angle) * canopyRadius;
            const rimZ = Math.sin(angle) * canopyRadius;
            const lineGeo = new THREE.BufferGeometry().setFromPoints([
                new THREE.Vector3(rimX, canopySkirtY, rimZ),
                new THREE.Vector3(0, swivelY, 0)
            ]);
            const line = new THREE.Line(lineGeo, lineMat);
            this.parachuteGroup.add(line);
        }

        this.parachuteGroup.visible = false;
        this.rocketGroup.add(this.parachuteGroup);
    }

    createRadialShadowTexture() {
        const canvas = document.createElement('canvas');
        canvas.width = 128;
        canvas.height = 128;
        const ctx = canvas.getContext('2d');
        const gradient = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
        gradient.addColorStop(0, 'rgba(10, 16, 26, 0.7)');
        gradient.addColorStop(0.35, 'rgba(10, 16, 26, 0.4)');
        gradient.addColorStop(0.7, 'rgba(10, 16, 26, 0.12)');
        gradient.addColorStop(1, 'rgba(10, 16, 26, 0.0)');
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, 128, 128);
        const texture = new THREE.CanvasTexture(canvas);
        return texture;
    }

    setupGroundProjection() {
        this.groundProjectionGroup = new THREE.Group();
        this.groundProjectionGroup.frustumCulled = false;

        // 1. Dynamic Soft Altitude Shadow Disk (communicates ROCKET -> AIR -> GROUND)
        const shadowGeo = new THREE.PlaneGeometry(1.6, 1.6);
        const shadowMat = new THREE.MeshBasicMaterial({
            map: this.createRadialShadowTexture(),
            transparent: true,
            opacity: 0.45,
            depthWrite: false
        });
        this.groundShadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
        this.groundShadowMesh.rotation.x = -Math.PI / 2;
        this.groundShadowMesh.position.y = 0.035;
        this.groundShadowMesh.frustumCulled = false;
        this.groundProjectionGroup.add(this.groundShadowMesh);

        // 2. High-Contrast Ground Reticle & Crosshairs
        this.groundReticle = new THREE.Group();
        this.groundReticle.frustumCulled = false;
        const ringGeo = new THREE.RingGeometry(0.35, 0.48, 36);
        const ringMat = new THREE.MeshBasicMaterial({
            color: 0xfbbf24,
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.85,
            depthWrite: false
        });
        const ringMesh = new THREE.Mesh(ringGeo, ringMat);
        ringMesh.rotation.x = -Math.PI / 2;
        ringMesh.frustumCulled = false;
        this.groundReticle.add(ringMesh);

        // 4 crisp crosshair ticks
        const tickPoints = [
            new THREE.Vector3(0, 0, -0.48), new THREE.Vector3(0, 0, -0.85),
            new THREE.Vector3(0, 0, 0.48), new THREE.Vector3(0, 0, 0.85),
            new THREE.Vector3(0.48, 0, 0), new THREE.Vector3(0.85, 0, 0),
            new THREE.Vector3(-0.48, 0, 0), new THREE.Vector3(-0.85, 0, 0)
        ];
        const tickGeo = new THREE.BufferGeometry().setFromPoints(tickPoints);
        const tickMat = new THREE.LineBasicMaterial({
            color: 0xfbbf24,
            transparent: true,
            opacity: 0.75,
            depthWrite: false
        });
        const tickLines = new THREE.LineSegments(tickGeo, tickMat);
        tickLines.frustumCulled = false;
        this.groundReticle.add(tickLines);
        this.groundReticle.position.y = 0.038;
        this.groundProjectionGroup.add(this.groundReticle);

        // 3. Vertical Altitude Plumb Line (connecting rocket base down to ground)
        const plumbPoints = [
            new THREE.Vector3(0, 0.04, 0),
            new THREE.Vector3(0, 1.0, 0)
        ];
        const plumbGeo = new THREE.BufferGeometry().setFromPoints(plumbPoints);
        const plumbMat = new THREE.LineDashedMaterial({
            color: 0xfacc15,
            dashSize: 1.4,
            gapSize: 0.9,
            transparent: true,
            opacity: 0.90,
            depthWrite: false
        });
        this.altitudePlumbLine = new THREE.Line(plumbGeo, plumbMat);
        this.altitudePlumbLine.frustumCulled = false;
        this.groundProjectionGroup.add(this.altitudePlumbLine);

        this.scene.add(this.groundProjectionGroup);
    }

    createBillboardBadge(lines, options = {}) {
        const width = options.width || 280;
        const height = options.height || 110;
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');

        // Dark navy translucent background
        ctx.fillStyle = options.bg || 'rgba(9, 16, 32, 0.90)';
        if (ctx.roundRect) {
            ctx.roundRect(4, 4, width - 8, height - 8, options.radius || 10);
        } else {
            ctx.rect(4, 4, width - 8, height - 8);
        }
        ctx.fill();

        // Telemetry amber/gold border
        ctx.strokeStyle = options.borderColor || 'rgba(251, 191, 36, 0.55)';
        ctx.lineWidth = options.borderWidth || 2;
        if (ctx.roundRect) {
            ctx.roundRect(4, 4, width - 8, height - 8, options.radius || 10);
        } else {
            ctx.rect(4, 4, width - 8, height - 8);
        }
        ctx.stroke();

        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        let y = options.startY || 30;
        lines.forEach(line => {
            ctx.fillStyle = line.color || '#ffffff';
            ctx.font = line.font || 'Bold 18px sans-serif';
            ctx.fillText(line.text, width / 2, y);
            y += (line.spacing || 26);
        });

        const texture = new THREE.CanvasTexture(canvas);
        texture.minFilter = THREE.LinearFilter;
        const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true, depthWrite: false });
        const sprite = new THREE.Sprite(spriteMat);
        const scale = options.scale || 1.0;
        sprite.scale.set((width / 100) * scale, (height / 100) * scale, 1);
        if (!this.billboardBadges) this.billboardBadges = [];
        this.billboardBadges.push({ sprite, width, height, scale });
        return sprite;
    }

    /**
     * Builds full 3D trajectory path ribbons and event markers
     */
    loadTrajectory(parser) {
        this.flightData = parser;
        this.isLoaded = true;
        this.billboardBadges = [];

        // Clear existing trajectory
        while (this.trajectoryGroup.children.length > 0) {
            const obj = this.trajectoryGroup.children[0];
            this.trajectoryGroup.remove(obj);
        }

        if (!parser.records || parser.records.length < 2) return;

        const records = parser.records;
        const apogeeT = parser.meta.apogeeTime || 4.8;

        // Helper to convert OpenRocket to Three.js coordinates
        // OpenRocket: posX = East (+X), alt = Up (+Y), posZ = North (-Z in Three.js)
        const toVec3 = (r) => new THREE.Vector3(r.posX, r.alt + 0.6, -r.posZ);
        
        // Filter points to ensure monotonic spatial progress (avoiding zero-distance Frenet frame collapse)
        const filteredPoints = [];
        for (let i = 0; i < records.length; i++) {
            const pt = toVec3(records[i]);
            if (filteredPoints.length === 0 || pt.distanceTo(filteredPoints[filteredPoints.length - 1]) >= 0.25) {
                filteredPoints.push(pt);
            }
        }
        if (records.length > 0) {
            filteredPoints.push(toVec3(records[records.length - 1]));
        }

        // Create main trajectory tube with super-thin black outline and high-contrast telemetry amber core
        if (filteredPoints.length >= 2) {
            const curve = new THREE.CatmullRomCurve3(filteredPoints);

            // 1. Super-thin black outline tube (inverted hull / back-side mesh for silhouette contrast against any background)
            const outlineGeo = new THREE.TubeGeometry(curve, 320, 0.029, 8, false);
            const outlineMat = new THREE.MeshBasicMaterial({
                color: 0x020617, // deep black outline
                side: THREE.BackSide,
                depthWrite: true
            });
            const outlineTube = new THREE.Mesh(outlineGeo, outlineMat);
            outlineTube.renderOrder = 1;
            this.trajectoryGroup.add(outlineTube);

            // 2. Core luminous trajectory tube (slender precision flight path matching airframe scale)
            const coreGeo = new THREE.TubeGeometry(curve, 320, 0.022, 8, false);
            const coreMat = new THREE.MeshBasicMaterial({
                color: 0xf59e0b,
                side: THREE.FrontSide,
                depthWrite: true
            });
            const coreTube = new THREE.Mesh(coreGeo, coreMat);
            coreTube.renderOrder = 2;
            this.trajectoryGroup.add(coreTube);

            // 3. High-altitude crisp line backup for distant visibility
            const lineGeo = new THREE.BufferGeometry().setFromPoints(curve.getPoints(filteredPoints.length * 3));
            const lineMat = new THREE.LineBasicMaterial({
                color: 0xfbbf24,
                transparent: true,
                opacity: 0.85
            });
            const trajLine = new THREE.Line(lineGeo, lineMat);
            this.trajectoryGroup.add(trajLine);
        }

        // Sub-rocket Ground Track Projection (dashed telemetry amber track on terrain)
        const groundPoints = records.map(r => new THREE.Vector3(r.posX, 0.04, -r.posZ));
        if (groundPoints.length >= 2) {
            const groundCurve = new THREE.CatmullRomCurve3(groundPoints);
            const groundGeo = new THREE.BufferGeometry().setFromPoints(groundCurve.getPoints(records.length * 2));
            const groundMat = new THREE.LineDashedMaterial({
                color: 0xf59e0b,
                dashSize: 2.0,
                gapSize: 1.2,
                transparent: true,
                opacity: 0.75,
                depthWrite: false
            });
            const groundLine = new THREE.Line(groundGeo, groundMat);
            groundLine.computeLineDistances();
            this.trajectoryGroup.add(groundLine);
        }

        // 1. Launch Badge and Target Ring at Pad (0, 0, 0)
        const launchRingGeo = new THREE.RingGeometry(1.2, 1.45, 36);
        const launchRingMat = new THREE.MeshBasicMaterial({ color: 0xfbbf24, side: THREE.DoubleSide, transparent: true, opacity: 0.85, depthWrite: false });
        const launchRing = new THREE.Mesh(launchRingGeo, launchRingMat);
        launchRing.rotation.x = -Math.PI / 2;
        launchRing.position.set(0, 0.04, 0);
        this.trajectoryGroup.add(launchRing);

        const launchBadge = this.createBillboardBadge([
            { text: 'Launch', font: 'Bold 28px sans-serif', color: '#ffffff', spacing: 32 },
            { text: 't = 0.0s', font: '22px monospace', color: '#fbbf24' }
        ], { width: 220, height: 90, startY: 34, scale: 0.9, radius: 10, borderColor: 'rgba(251, 191, 36, 0.55)' });
        launchBadge.position.set(-2.2, 1.0, 0);
        this.trajectoryGroup.add(launchBadge);

        // 2. Apogee Badge, Glowing Point, and Plumb Line at Trajectory Peak
        const apogeeState = parser.sample(apogeeT) || records[Math.floor(records.length / 2)];
        if (apogeeState) {
            const apogeePt = new THREE.Vector3(apogeeState.posX, apogeeState.alt + 0.6, -apogeeState.posZ);
            const apogeeGround = new THREE.Vector3(apogeeState.posX, 0.04, -apogeeState.posZ);

            // Glowing amber/gold node at peak
            const apogeeNodeGeo = new THREE.SphereGeometry(0.38, 16, 16);
            const apogeeNodeMat = new THREE.MeshBasicMaterial({ color: 0xfbbf24 });
            const apogeeNode = new THREE.Mesh(apogeeNodeGeo, apogeeNodeMat);
            apogeeNode.position.copy(apogeePt);
            this.trajectoryGroup.add(apogeeNode);

            // High-contrast vertical plumb line from peak to ground
            const plumbGeo = new THREE.BufferGeometry().setFromPoints([apogeePt, apogeeGround]);
            const plumbMat = new THREE.LineDashedMaterial({
                color: 0xfacc15,
                dashSize: 1.8,
                gapSize: 1.2,
                transparent: true,
                opacity: 0.85,
                depthWrite: false
            });
            const plumbLine = new THREE.Line(plumbGeo, plumbMat);
            plumbLine.computeLineDistances();
            this.trajectoryGroup.add(plumbLine);

            // Apogee Callout Badge
            const apogeeBadge = this.createBillboardBadge([
                { text: 'Apogee', font: 'Bold 30px sans-serif', color: '#ffffff', spacing: 34 },
                { text: `t = ${apogeeT.toFixed(1)}s`, font: '22px monospace', color: '#fbbf24', spacing: 32 },
                { text: `${parser.meta.maxAltitude ? parser.meta.maxAltitude.toFixed(1) : apogeeState.alt.toFixed(1)} m`, font: 'Bold 32px monospace', color: '#ffffff' }
            ], { width: 240, height: 130, startY: 34, scale: 2.2, radius: 12, borderColor: 'rgba(251, 191, 36, 0.65)' });
            apogeeBadge.position.set(apogeePt.x, apogeePt.y + 4.2, apogeePt.z);
            this.trajectoryGroup.add(apogeeBadge);
        }

        // 3. Touchdown Badge and Target Ring at Landing Spot
        const lastRecord = records[records.length - 1];
        const landingPos = new THREE.Vector3(lastRecord.posX, 0.04, -lastRecord.posZ);

        const landingRingGeo = new THREE.RingGeometry(1.2, 1.45, 36);
        const landingRingMat = new THREE.MeshBasicMaterial({ color: 0xf59e0b, side: THREE.DoubleSide, transparent: true, opacity: 0.85, depthWrite: false });
        const landingRing = new THREE.Mesh(landingRingGeo, landingRingMat);
        landingRing.rotation.x = -Math.PI / 2;
        landingRing.position.copy(landingPos);
        this.trajectoryGroup.add(landingRing);

        const touchdownBadge = this.createBillboardBadge([
            { text: 'Touchdown', font: 'Bold 28px sans-serif', color: '#ffffff', spacing: 32 },
            { text: `t = ${lastRecord.time.toFixed(1)}s`, font: '22px monospace', color: '#f59e0b' }
        ], { width: 240, height: 90, startY: 34, scale: 1.6, radius: 10, borderColor: 'rgba(245, 158, 11, 0.65)' });
        touchdownBadge.position.set(landingPos.x + 2.0, 2.5, landingPos.z);
        this.trajectoryGroup.add(touchdownBadge);

        // 4. Downrange Drift Ground Line and Badge
        const driftDist = lastRecord.lateralDist || landingPos.distanceTo(new THREE.Vector3(0, 0, 0));
        const driftLineGeo = new THREE.BufferGeometry().setFromPoints([
            new THREE.Vector3(0, 0.05, 0),
            landingPos
        ]);
        const driftLineMat = new THREE.LineDashedMaterial({
            color: 0xfbbf24,
            dashSize: 1.5,
            gapSize: 1.0,
            transparent: true,
            opacity: 0.85,
            depthWrite: false
        });
        const driftLine = new THREE.Line(driftLineGeo, driftLineMat);
        driftLine.computeLineDistances();
        this.trajectoryGroup.add(driftLine);

        const midPoint = new THREE.Vector3(landingPos.x * 0.5, 0.05, landingPos.z * 0.5);
        const driftBadge = this.createBillboardBadge([
            { text: 'Downrange Drift', font: '22px sans-serif', color: '#cbd5e1', spacing: 30 },
            { text: `${driftDist.toFixed(1)} m`, font: 'Bold 28px monospace', color: '#fbbf24' }
        ], { width: 260, height: 90, startY: 34, scale: 1.4, radius: 10, borderColor: 'rgba(251, 191, 36, 0.55)', bg: 'rgba(9, 16, 32, 0.88)' });
        driftBadge.position.set(midPoint.x, 1.2, midPoint.z);
        this.trajectoryGroup.add(driftBadge);
    }

    /**
     * Updates rocket state to current playback timestamp t
     * @param {number} t Current simulation time in seconds
     */
    update(t) {
        if (!this.flightData || !this.isLoaded) return;

        const state = this.flightData.sample(t);
        if (!state) return;

        // Position update
        const posX = state.posX;
        const posY = Math.max(0.6, state.alt + 0.6);
        const posZ = -state.posZ; // North is -Z
        this.rocketGroup.position.set(posX, posY, posZ);

        // Ground projection & Altitude shadow update (ROCKET -> AIR -> GROUND)
        if (this.groundProjectionGroup) {
            const alt = Math.max(0, state.alt);
            if (alt > 0.08) {
                this.groundProjectionGroup.visible = true;

                // Position shadow & reticle directly below rocket on terrain
                this.groundShadowMesh.position.set(posX, 0.035, posZ);
                this.groundReticle.position.set(posX, 0.038, posZ);

                // Scale and soften ground shadow with altitude
                const shadowScale = Math.min(3.8, 1.0 + alt * 0.02);
                this.groundShadowMesh.scale.set(shadowScale, shadowScale, 1);
                this.groundShadowMesh.material.opacity = Math.max(0.12, 0.45 - alt * 0.0018);

                // Dynamic vertical plumb line from terrain up to rocket base
                const posAttr = this.altitudePlumbLine.geometry.attributes.position;
                posAttr.setXYZ(0, posX, 0.04, posZ);
                posAttr.setXYZ(1, posX, posY, posZ);
                posAttr.needsUpdate = true;
                this.altitudePlumbLine.computeLineDistances();
                if (this.altitudePlumbLine.geometry.attributes.lineDistance) {
                    this.altitudePlumbLine.geometry.attributes.lineDistance.needsUpdate = true;
                }
                this.altitudePlumbLine.visible = true;
            } else {
                // Resting on pad: keep contact shadow under rocket, hide vertical line
                this.groundShadowMesh.position.set(posX, 0.035, posZ);
                this.groundShadowMesh.scale.set(1.0, 1.0, 1);
                this.groundShadowMesh.material.opacity = 0.45;
                this.groundReticle.position.set(posX, 0.038, posZ);
                this.altitudePlumbLine.visible = false;
            }
        }

        // High-altitude rocket tracking beacon visibility (fades in as camera pulls back)
        if (this.rocketBeacon && this.camera) {
            const camDist = this.camera.position.distanceTo(this.rocketGroup.position);
            this.rocketBeacon.quaternion.copy(this.camera.quaternion);

            if (camDist < 16) {
                this.rocketBeacon.visible = false;
            } else if (camDist < 60) {
                this.rocketBeacon.visible = true;
                const factor = (camDist - 16) / 44;
                const op = factor * 0.80;
                if (this.rocketBeaconMat) this.rocketBeaconMat.opacity = op;
                if (this.rocketBeaconTickMat) this.rocketBeaconTickMat.opacity = op * 0.85;
                const scale = 1.0 + factor * 0.45;
                this.rocketBeacon.scale.set(scale, scale, scale);
            } else {
                this.rocketBeacon.visible = true;
                if (this.rocketBeaconMat) this.rocketBeaconMat.opacity = 0.85;
                if (this.rocketBeaconTickMat) this.rocketBeaconTickMat.opacity = 0.75;
                const scale = Math.min(2.5, 1.45 + (camDist - 60) * 0.008);
                this.rocketBeacon.scale.set(scale, scale, scale);
            }
        }

        // Rotation update (Zenith & Azimuth from OpenRocket)
        // Zenith is angle with horizontal ground (90° = vertical up)
        // Azimuth is compass heading (0° = North = -Z, 90° = East = +X, 180° = South = +Z, 270° = West = -X)
        const deployT = (this.flightData && this.flightData.meta && this.flightData.meta.deployTime) || 
                        (this.flightData && this.flightData.meta && this.flightData.meta.apogeeTime) || 4.65;
        const flightT = (this.flightData && this.flightData.meta && (this.flightData.meta.flightTime || this.flightData.meta.landingTime || this.flightData.meta.duration)) || 26.89;
        const isUnderChute = t >= deployT;

        if (isUnderChute) {
            // Under parachute: rocket hangs slightly tilted and oscillates gently during descent
            // Once touched down on ground (or t >= flightT), rocket rests upright and stable
            const isLanded = t >= flightT || state.alt <= 0.05;
            const sway = isLanded ? 0 : Math.sin(t * 2.5) * 0.04;
            this.rocketGroup.rotation.set(sway, 0, sway * 0.5);
            this.parachuteGroup.visible = true;
            // Smooth canopy scale-in animation outward from nose tip at deployment
            const chuteProgress = Math.min(1.0, (t - deployT) / 0.4);
            this.parachuteGroup.scale.set(chuteProgress, chuteProgress, chuteProgress);
        } else {
            this.parachuteGroup.visible = false;

            // Rocket flight orientation: tip leads along the 3D trajectory
            const liftoffEvent = this.flightData.events ? this.flightData.events.find(e => e.name === "LIFTOFF" || e.name === "LAUNCH") : null;
            const liftoffT = liftoffEvent ? liftoffEvent.time : 0.1;

            // Pad launch rail orientation from zenith / azimuth
            const padZenith = (state.zenith !== undefined && !isNaN(state.zenith)) ? state.zenith : 90;
            const padAzimuth = (state.azimuth !== undefined && !isNaN(state.azimuth)) ? state.azimuth : 90;
            const theta = padZenith * (Math.PI / 180);
            const psi = padAzimuth * (Math.PI / 180);
            const padDir = new THREE.Vector3(
                Math.cos(theta) * Math.sin(psi),
                Math.sin(theta),
                -Math.cos(theta) * Math.cos(psi)
            ).normalize();

            let targetDir = padDir.clone();

            if (t > liftoffT) {
                // Compute instantaneous trajectory tangent vector
                const dt = 0.04;
                const t1 = Math.max(0, t - dt);
                const t2 = Math.min(deployT, t + dt);
                const s1 = this.flightData.sample(t1);
                const s2 = this.flightData.sample(t2);

                if (s1 && s2) {
                    const tan = new THREE.Vector3(
                        s2.posX - s1.posX,
                        s2.alt - s1.alt,
                        -(s2.posZ - s1.posZ)
                    );
                    if (tan.lengthSq() > 1e-6) {
                        tan.normalize();
                        // Smooth blend off the launch rail during first 0.15s after liftoff
                        const blend = Math.min(1.0, (t - liftoffT) / 0.15);
                        targetDir.lerpVectors(padDir, tan, blend).normalize();
                    }
                }
            }

            // Rocket model is constructed with tip along +Y: rotate from +Y to targetDir
            this.rocketGroup.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), targetDir);
        }

        // Thrust / Flame effect
        const isThrusting = state.thrust > 0.05 && t <= (this.flightData.meta.burnoutTime || 1.65);
        if (isThrusting) {
            this.flameMesh.visible = true;
            const flicker = 0.8 + Math.random() * 0.4;
            this.flameMesh.scale.set(flicker, flicker * (0.8 + (state.thrust / 25)), flicker);
            this.exhaustLight.intensity = 2.5 + Math.random() * 1.5;

            // Spawn exhaust smoke particle
            this.spawnExhaustParticle(this.rocketGroup.position);
        } else {
            this.flameMesh.visible = false;
            this.exhaustLight.intensity = 0;
        }

        // Update active particles
        this.updateParticles();

        // Update Camera based on active mode
        this.updateCamera(posX, posY, posZ, state);
    }

    spawnExhaustParticle(rocketPos) {
        if (this.particles.length > 80) return; // limit count

        const pGeo = new THREE.DodecahedronGeometry(0.08 + Math.random() * 0.06);
        const pMat = new THREE.MeshBasicMaterial({
            color: Math.random() > 0.4 ? 0xffffff : 0x94a3b8,
            transparent: true,
            opacity: 0.6
        });
        const mesh = new THREE.Mesh(pGeo, pMat);
        
        // Spawn along the rocket tail direction opposite to flight
        const tailDir = new THREE.Vector3(0, -1, 0).applyQuaternion(this.rocketGroup.quaternion);
        const spawnPos = rocketPos.clone().addScaledVector(tailDir, 0.25);
        mesh.position.copy(spawnPos);
        mesh.position.x += (Math.random() - 0.5) * 0.08;
        mesh.position.y += (Math.random() - 0.5) * 0.08;
        mesh.position.z += (Math.random() - 0.5) * 0.08;

        this.scene.add(mesh);
        this.particles.push({
            mesh,
            vel: tailDir.clone().multiplyScalar(0.4 + Math.random() * 0.3).add(
                new THREE.Vector3((Math.random() - 0.5) * 0.15, (Math.random() - 0.5) * 0.15, (Math.random() - 0.5) * 0.15)
            ),
            life: 0.8
        });
    }

    updateParticles() {
        for (let i = this.particles.length - 1; i >= 0; i--) {
            const p = this.particles[i];
            p.life -= 0.03;
            p.mesh.position.addScaledVector(p.vel, 0.04);
            p.mesh.scale.multiplyScalar(1.04);
            p.mesh.material.opacity = p.life * 0.6;

            if (p.life <= 0) {
                this.scene.remove(p.mesh);
                p.mesh.geometry.dispose();
                p.mesh.material.dispose();
                this.particles.splice(i, 1);
            }
        }
    }

    updateCamera(rx, ry, rz, state) {
        const rocketPos = new THREE.Vector3(rx, ry, rz);

        if (this.cameraMode === "chase") {
            if (!this.lastRocketPos) {
                this.lastRocketPos = rocketPos.clone();
                this.controls.target.copy(rocketPos);
                const offset = new THREE.Vector3(-4.5, 1.8, 5.0).normalize().multiplyScalar(this.chaseDistance || 6.5);
                this.camera.position.copy(rocketPos).add(offset);
            } else {
                // Move camera and target by the exact flight displacement of the rocket
                const rocketShift = new THREE.Vector3().subVectors(rocketPos, this.lastRocketPos);
                this.camera.position.add(rocketShift);
                this.controls.target.copy(rocketPos);
                this.lastRocketPos.copy(rocketPos);
            }

            // Dynamically track user's active zoom distance from OrbitControls
            this.chaseDistance = this.camera.position.distanceTo(rocketPos);

            // Ground clamp so zoomed-out camera doesn't dip under ground
            if (this.camera.position.y < 0.35) {
                this.camera.position.y = 0.35;
            }

            // Update OrbitControls so mouse wheel zoom, pinch, and orbit are processed smoothly
            this.controls.update();
        } else if (this.cameraMode === "pad") {
            // Launch site ground tracker beside pad looking smoothly up into the sky
            this.camera.position.set(9.0, 1.5, 12.0);
            this.controls.target.lerp(rocketPos, 0.08);
            this.controls.update();
        } else if (this.cameraMode === "apogee") {
            // High altitude vantage view framed around trajectory apex and arch
            const maxAlt = (this.flightData && this.flightData.meta && this.flightData.meta.maxAltitude) || 95;
            const targetCamPos = new THREE.Vector3(10, Math.max(70, maxAlt * 0.85), Math.max(130, maxAlt * 1.7));
            const targetLook = new THREE.Vector3(14, maxAlt * 0.45, 0);
            this.camera.position.lerp(targetCamPos, 0.05);
            this.controls.target.lerp(targetLook, 0.05);
            this.controls.update();
        } else if (this.cameraMode === "free") {
            // User free orbit controls
            this.controls.update();
        }
    }

    setCameraMode(mode) {
        this.cameraMode = mode;
        const rx = this.rocketGroup ? this.rocketGroup.position.x : 0;
        const ry = this.rocketGroup ? this.rocketGroup.position.y : 0.6;
        const rz = this.rocketGroup ? this.rocketGroup.position.z : 0;
        const rocketPos = new THREE.Vector3(rx, ry, rz);

        if (mode === "chase") {
            const dist = this.chaseDistance || 6.5;
            const offsetDir = new THREE.Vector3(-4.5, 1.8, 5.0).normalize();
            this.chaseDistance = dist;
            this.controls.target.copy(rocketPos);
            this.camera.position.copy(rocketPos).addScaledVector(offsetDir, dist);
            this.lastRocketPos = rocketPos.clone();
            this.controls.update();
        } else if (mode === "pad") {
            this.camera.position.set(9.0, 1.5, 12.0);
            this.controls.target.copy(rocketPos);
            this.controls.update();
        } else if (mode === "apogee") {
            const maxAlt = (this.flightData && this.flightData.meta && this.flightData.meta.maxAltitude) || 95;
            const targetCamPos = new THREE.Vector3(10, Math.max(70, maxAlt * 0.85), Math.max(130, maxAlt * 1.7));
            const targetLook = new THREE.Vector3(14, maxAlt * 0.45, 0);
            this.camera.position.copy(targetCamPos);
            this.controls.target.copy(targetLook);
            this.controls.update();
        } else if (mode === "free") {
            this.controls.update();
        }
    }

    zoomCamera(deltaFactor) {
        if (!this.controls || !this.camera) return;
        const target = this.controls.target;
        const camPos = this.camera.position;
        const offset = new THREE.Vector3().subVectors(camPos, target);
        const curDist = offset.length();
        const newDist = Math.max(1.5, Math.min(1500, curDist * (1 + deltaFactor)));
        offset.normalize().multiplyScalar(newDist);
        this.camera.position.copy(target).add(offset);
        if (this.cameraMode === "chase") {
            this.chaseDistance = newDist;
        }
        this.controls.update();
    }

    render() {
        if (this.controls && this.camera) {
            const dx = this.camera.position.x - this.controls.target.x;
            const dz = this.camera.position.z - this.controls.target.z;
            const angleRad = Math.atan2(dx, dz);
            const angleDeg = angleRad * (180 / Math.PI);
            const compassDial = document.getElementById("compass-dial");
            if (compassDial) {
                compassDial.style.transform = `rotate(${-angleDeg}deg)`;
            }

            // Screen-space constant scale attenuation for technical callout badges
            if (this.billboardBadges && this.billboardBadges.length > 0) {
                this.billboardBadges.forEach(item => {
                    if (item.sprite && item.sprite.parent) {
                        const dist = this.camera.position.distanceTo(item.sprite.position);
                        const s = Math.max(0.35, Math.min(3.8, dist * 0.024)) * item.scale;
                        item.sprite.scale.set((item.width / 100) * s, (item.height / 100) * s, 1);
                    }
                });
            }
        }
        this.renderer.render(this.scene, this.camera);
    }

    onWindowResize() {
        if (!this.container) return;
        const width = this.container.clientWidth;
        const height = this.container.clientHeight;
        this.camera.aspect = width / height;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(width, height);
    }
}


/**
 * OpenRocket 3D Flight Visualizer - Synchronized Audio System
 * Uses Web Audio API with procedural acoustic synthesis.
 * Fully offline and zero-CORS ready (no external audio assets required).
 */

class FlightAudioManager {
    constructor() {
        this.ctx = null;
        this.masterGain = null;
        this.compressor = null;
        this.motorGain = null;
        this.windGain = null;
        this.motorSource = null;
        this.windSource = null;

        // Preloaded synthesized AudioBuffers
        this.buffers = {};

        // Tracking active one-shot nodes for instant cancellation
        this.activeOneShots = new Set();

        // Audio state
        this.volume = 0.70;
        this.isMuted = false;
        this.isPlaying = false;
        this.lastTime = 0;
        this.firedEvents = new Set();
        this.flightData = null;

        // DOM elements
        this.soundBtn = null;
        this.volumeSlider = null;
        this.iconOn = null;
        this.iconOff = null;
    }

    /**
     * Attaches UI control elements
     */
    initUI(soundBtn, volumeSlider, iconOn, iconOff) {
        this.soundBtn = soundBtn;
        this.volumeSlider = volumeSlider;
        this.iconOn = iconOn;
        this.iconOff = iconOff;

        if (this.soundBtn) {
            this.soundBtn.addEventListener("click", () => {
                this.ensureAudioContext();
                this.toggleMute();
            });
        }

        if (this.volumeSlider) {
            this.volumeSlider.addEventListener("input", (e) => {
                this.ensureAudioContext();
                this.setVolume(parseFloat(e.target.value));
            });
        }

        this.updateUI();
    }

    /**
     * Initializes AudioContext upon user gesture
     */
    ensureAudioContext() {
        if (!this.ctx) {
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            if (!AudioCtx) return null;
            this.ctx = new AudioCtx();
            this.buildAudioGraph();
            this.synthesizeBuffers();
            this.startContinuousLoops();
        }
        if (this.ctx && this.ctx.state === "suspended") {
            this.ctx.resume();
        }
        return this.ctx;
    }

    /**
     * Builds master routing graph with dynamics compressor/limiter
     */
    buildAudioGraph() {
        if (!this.ctx) return;

        // Dynamics compressor to guarantee clean headroom and prevent clipping
        this.compressor = this.ctx.createDynamicsCompressor();
        this.compressor.threshold.setValueAtTime(-4, this.ctx.currentTime);
        this.compressor.knee.setValueAtTime(8, this.ctx.currentTime);
        this.compressor.ratio.setValueAtTime(6, this.ctx.currentTime);
        this.compressor.attack.setValueAtTime(0.003, this.ctx.currentTime);
        this.compressor.release.setValueAtTime(0.15, this.ctx.currentTime);
        this.compressor.connect(this.ctx.destination);

        // Master Gain Node
        this.masterGain = this.ctx.createGain();
        this.masterGain.gain.setValueAtTime(this.isMuted ? 0 : this.volume, this.ctx.currentTime);
        this.masterGain.connect(this.compressor);

        // Motor Thrust Gain Node (routes to master)
        this.motorGain = this.ctx.createGain();
        this.motorGain.gain.setValueAtTime(0, this.ctx.currentTime);
        this.motorGain.connect(this.masterGain);

        // Wind / Airflow Gain Node (routes to master)
        this.windGain = this.ctx.createGain();
        this.windGain.gain.setValueAtTime(0, this.ctx.currentTime);
        this.windGain.connect(this.masterGain);
    }

    /**
     * Procedurally synthesizes realistic aerospace sound buffers
     */
    synthesizeBuffers() {
        if (!this.ctx) return;
        const sr = this.ctx.sampleRate;

        // 1. Ignition Sound Buffer (0.45s): spark crackle followed by rapid flame rush
        const ignLen = Math.floor(sr * 0.45);
        const ignBuf = this.ctx.createBuffer(1, ignLen, sr);
        const ignData = ignBuf.getChannelData(0);
        let b0 = 0, b1 = 0;
        for (let i = 0; i < ignLen; i++) {
            const t = i / sr;
            const white = Math.random() * 2 - 1;
            b0 = 0.95 * b0 + white * 0.05;
            b1 = 0.85 * b1 + white * 0.15;
            let env = 0;
            if (t < 0.08) {
                env = (t / 0.08) * 0.35 + (Math.random() > 0.93 ? 0.35 : 0);
            } else if (t < 0.22) {
                env = 0.35 + ((t - 0.08) / 0.14) * 0.65;
            } else {
                env = Math.max(0, 1.0 - ((t - 0.22) / 0.23));
            }
            ignData[i] = (b0 * 0.6 + (white - b1) * 0.4) * env * 0.7;
        }
        this.buffers.ignition = ignBuf;

        // 2. Motor Continuous Looping Buffer (2.0s): deep resonant acoustic combustion rumble & hiss
        const motLen = Math.floor(sr * 2.0);
        const motBuf = this.ctx.createBuffer(1, motLen, sr);
        const motData = motBuf.getChannelData(0);
        let last = 0;
        for (let i = 0; i < motLen; i++) {
            const t = i / sr;
            const white = Math.random() * 2 - 1;
            last = (last + (0.045 * white)) / 1.045;
            const combustion = Math.sin(2 * Math.PI * 48 * t) * 0.14 + Math.sin(2 * Math.PI * 96 * t + 0.8) * 0.09;
            const hiss = (white - last) * 0.16;
            motData[i] = (last * 1.7 + combustion + hiss) * 0.55;
        }
        // Seamless crossfade boundary
        const xfadeM = Math.floor(sr * 0.06);
        for (let i = 0; i < xfadeM; i++) {
            const p = i / xfadeM;
            motData[i] = motData[i] * p + motData[motLen - xfadeM + i] * (1 - p);
        }
        this.buffers.motor = motBuf;

        // 3. Ejection Charge Sound Buffer (0.35s): sharp pyrotechnic pop & hollow body resonance
        const ejLen = Math.floor(sr * 0.35);
        const ejBuf = this.ctx.createBuffer(1, ejLen, sr);
        const ejData = ejBuf.getChannelData(0);
        for (let i = 0; i < ejLen; i++) {
            const t = i / sr;
            const env = Math.exp(-t * 24);
            const freq = 175 * Math.exp(-t * 22) + 55;
            const pop = Math.sin(2 * Math.PI * freq * t);
            const noise = (Math.random() * 2 - 1) * Math.exp(-t * 40);
            ejData[i] = (pop * 0.7 + noise * 0.35) * env * 0.85;
        }
        this.buffers.ejection = ejBuf;

        // 4. Parachute Deployment Buffer (0.50s): fabric whip snap followed by canopy billow whoosh
        const chLen = Math.floor(sr * 0.50);
        const chBuf = this.ctx.createBuffer(1, chLen, sr);
        const chData = chBuf.getChannelData(0);
        let lp = 0;
        for (let i = 0; i < chLen; i++) {
            const t = i / sr;
            const white = Math.random() * 2 - 1;
            lp = 0.88 * lp + white * 0.12;
            const snap = (t < 0.04) ? Math.sin((t / 0.04) * Math.PI) * (white * 0.75 + (white - lp) * 0.55) : 0;
            const billowEnv = (t >= 0.03 && t <= 0.45) ? Math.sin(((t - 0.03) / 0.42) * Math.PI) : 0;
            const billow = lp * billowEnv * 0.6;
            chData[i] = (snap * 0.65 + billow) * 0.75;
        }
        this.buffers.parachute = chBuf;

        // 5. Descent Airflow / Wind Looping Buffer (3.0s): soft, gentle ambient air rush
        const wLen = Math.floor(sr * 3.0);
        const wBuf = this.ctx.createBuffer(1, wLen, sr);
        const wData = wBuf.getChannelData(0);
        let wf0 = 0, wf1 = 0;
        for (let i = 0; i < wLen; i++) {
            const white = Math.random() * 2 - 1;
            wf0 = 0.96 * wf0 + white * 0.04;
            wf1 = 0.90 * wf1 + white * 0.10;
            wData[i] = (wf0 * 0.75 + (wf1 - wf0) * 0.25) * 0.4;
        }
        // Seamless crossfade boundary
        const xfadeW = Math.floor(sr * 0.06);
        for (let i = 0; i < xfadeW; i++) {
            const p = i / xfadeW;
            wData[i] = wData[i] * p + wData[wLen - xfadeW + i] * (1 - p);
        }
        this.buffers.wind = wBuf;

        // 6. Landing / Touchdown Buffer (0.30s): restrained, lightweight model rocket turf thud
        const lLen = Math.floor(sr * 0.30);
        const lBuf = this.ctx.createBuffer(1, lLen, sr);
        const lData = lBuf.getChannelData(0);
        for (let i = 0; i < lLen; i++) {
            const t = i / sr;
            const env = Math.exp(-t * 26);
            const freq = 85 * Math.exp(-t * 20) + 38;
            const thud = Math.sin(2 * Math.PI * freq * t);
            const grass = (Math.random() * 2 - 1) * Math.exp(-t * 18) * 0.3;
            lData[i] = (thud * 0.65 + grass) * env * 0.55;
        }
        this.buffers.landing = lBuf;
    }

    /**
     * Starts continuous looping sources for motor and wind
     */
    startContinuousLoops() {
        if (!this.ctx || !this.buffers.motor || !this.buffers.wind) return;

        // Stop existing if any
        this.stopContinuousLoops();

        // 1. Motor loop
        this.motorSource = this.ctx.createBufferSource();
        this.motorSource.buffer = this.buffers.motor;
        this.motorSource.loop = true;
        this.motorSource.connect(this.motorGain);
        this.motorSource.start(0);

        // 2. Wind loop
        this.windSource = this.ctx.createBufferSource();
        this.windSource.buffer = this.buffers.wind;
        this.windSource.loop = true;
        this.windSource.connect(this.windGain);
        this.windSource.start(0);
    }

    /**
     * Stops continuous looping sources
     */
    stopContinuousLoops() {
        if (this.motorSource) {
            try { this.motorSource.stop(); } catch (e) {}
            this.motorSource.disconnect();
            this.motorSource = null;
        }
        if (this.windSource) {
            try { this.windSource.stop(); } catch (e) {}
            this.windSource.disconnect();
            this.windSource = null;
        }
    }

    /**
     * Plays a one-shot sound buffer
     */
    playOneShot(name, gainScale = 1.0) {
        if (!this.ctx || this.isMuted || !this.buffers[name]) return;
        if (this.ctx.state === "suspended") this.ctx.resume();

        const src = this.ctx.createBufferSource();
        src.buffer = this.buffers[name];

        const gainNode = this.ctx.createGain();
        gainNode.gain.setValueAtTime(gainScale, this.ctx.currentTime);

        src.connect(gainNode);
        gainNode.connect(this.masterGain);

        this.activeOneShots.add(src);
        src.onended = () => {
            this.activeOneShots.delete(src);
            try {
                src.disconnect();
                gainNode.disconnect();
            } catch (e) {}
        };

        src.start(0);
    }

    /**
     * Immediately cancels all active one-shot sound effects
     */
    stopAllOneShots() {
        this.activeOneShots.forEach(src => {
            try { src.stop(); } catch (e) {}
            try { src.disconnect(); } catch (e) {}
        });
        this.activeOneShots.clear();
    }

    /**
     * Assigns active flight data parser
     */
    setFlightData(flightData) {
        this.flightData = flightData;
        this.firedEvents.clear();
        this.lastTime = 0;
    }

    /**
     * Helper to safely set gain value on AudioParam with fallback
     */
    setGain(gainNode, val, smooth = true) {
        if (!gainNode || !this.ctx) return;
        const target = Math.max(0, val);
        if (smooth && this.ctx.state === "running") {
            try {
                gainNode.gain.setTargetAtTime(target, this.ctx.currentTime, 0.04);
            } catch (e) {}
        } else {
            try {
                gainNode.gain.setValueAtTime(target, this.ctx.currentTime);
            } catch (e) {}
        }
        gainNode.gain.value = target;
    }

    /**
     * Master volume control (0.0 to 1.0)
     */
    setVolume(val) {
        this.volume = Math.max(0, Math.min(1, val));
        this.setGain(this.masterGain, this.isMuted ? 0 : this.volume, true);
        this.updateUI();
    }

    /**
     * Mute / Unmute toggle
     */
    toggleMute() {
        this.isMuted = !this.isMuted;
        this.setGain(this.masterGain, this.isMuted ? 0 : this.volume, true);
        this.updateUI();
    }

    updateUI() {
        if (this.volumeSlider) {
            this.volumeSlider.value = this.volume;
        }
        if (this.iconOn && this.iconOff) {
            if (this.isMuted || this.volume === 0) {
                this.iconOn.style.display = "none";
                this.iconOff.style.display = "block";
                if (this.soundBtn) this.soundBtn.classList.add("muted");
            } else {
                this.iconOn.style.display = "block";
                this.iconOff.style.display = "none";
                if (this.soundBtn) this.soundBtn.classList.remove("muted");
            }
        }
    }

    /**
     * Playback started / resumed
     */
    onPlay(t) {
        this.ensureAudioContext();
        this.isPlaying = true;
        this.lastTime = t || 0;
        if (!this.motorSource || !this.windSource) {
            this.startContinuousLoops();
        }
    }

    /**
     * Playback paused
     */
    onPause() {
        this.isPlaying = false;
        this.stopAllOneShots();
        this.setGain(this.motorGain, 0, false);
        this.setGain(this.windGain, 0, false);
    }

    /**
     * Scrubbed timeline to new time t
     */
    onSeek(t, isPlaying) {
        this.stopAllOneShots();
        this.lastTime = t;
        this.firedEvents.clear();

        // Mark past events as already fired so they don't replay
        if (this.flightData && this.flightData.events) {
            this.flightData.events.forEach(ev => {
                if (ev.time <= t) {
                    this.firedEvents.add(ev.name);
                }
            });
        }
        // Also mark key milestones if past
        if (this.flightData && this.flightData.meta) {
            if (t >= 0.05) this.firedEvents.add("IGNITION");
            if (t >= (this.flightData.meta.burnoutTime || 1.65)) this.firedEvents.add("BURNOUT");
            const deployT = this.flightData.meta.deployTime || this.flightData.meta.apogeeTime || 4.65;
            if (t >= deployT) {
                this.firedEvents.add("EJECTION_CHARGE");
                this.firedEvents.add("EJECTION");
                this.firedEvents.add("PARACHUTE_DEPLOYED");
                this.firedEvents.add("PARACHUTE");
            }
            if (t >= (this.flightData.meta.flightTime || this.flightData.meta.landingTime || this.flightData.meta.duration || 26.89)) {
                this.firedEvents.add("GROUND_HIT");
                this.firedEvents.add("LANDING");
            }
        }

        // Immediately update continuous sound gains to match new timestamp
        this.update(t, isPlaying, 1.0);
    }

    /**
     * Playback reset to 0 (restart or loop)
     */
    onReset() {
        this.stopAllOneShots();
        this.firedEvents.clear();
        this.lastTime = 0;
        this.setGain(this.motorGain, 0, false);
        this.setGain(this.windGain, 0, false);
        if (!this.motorSource || !this.windSource) {
            this.startContinuousLoops();
        }
    }

    /**
     * Simulation reached final timestamp (Loop OFF)
     */
    onPlaybackEnd() {
        this.isPlaying = false;
        this.stopAllOneShots();
        this.setGain(this.motorGain, 0, false);
        this.setGain(this.windGain, 0, false);
    }

    /**
     * Main animation frame audio update
     * Synchronizes events, motor thrust gain, and descent wind
     */
    update(t, isPlaying, speed = 1.0) {
        if (!this.ctx || !this.flightData) return;

        // If not playing, keep continuous gains muted
        if (!isPlaying) {
            this.setGain(this.motorGain, 0, false);
            this.setGain(this.windGain, 0, false);
            return;
        }

        const meta = this.flightData.meta;
        const deployT = meta.deployTime || meta.apogeeTime || 4.65;
        const burnoutT = meta.burnoutTime || 1.65;
        const durationT = meta.flightTime || meta.landingTime || meta.duration || 26.89;
        const state = this.flightData.sample(t);

        // Ensure loops are active if playing
        if (!this.motorSource || !this.windSource) {
            this.startContinuousLoops();
        }

        // --- 1. EVENT DETECTION (Forward playback crossing) ---
        if (t > this.lastTime) {
            // A. Ignition / Launch
            if (t >= 0.0 && this.lastTime <= 0.08 && !this.firedEvents.has("IGNITION")) {
                this.firedEvents.add("IGNITION");
                this.playOneShot("ignition", 0.85);
            }

            // B. Ejection Charge
            const ejectionEv = this.flightData.events ? this.flightData.events.find(e => e.name.includes("EJECTION")) : null;
            const ejectionT = ejectionEv ? ejectionEv.time : deployT;
            if (this.lastTime <= ejectionT && t >= ejectionT && !this.firedEvents.has("EJECTION")) {
                this.firedEvents.add("EJECTION");
                this.playOneShot("ejection", 0.90);
            }

            // C. Parachute Deployment
            const chuteEv = this.flightData.events ? this.flightData.events.find(e => e.name.includes("PARACHUTE") || e.name.includes("RECOVERY") || e.name.includes("DEPLOYMENT")) : null;
            const chuteT = chuteEv ? chuteEv.time : deployT;
            if (this.lastTime <= chuteT && t >= chuteT && !this.firedEvents.has("PARACHUTE")) {
                this.firedEvents.add("PARACHUTE");
                this.playOneShot("parachute", 0.80);
            }

            // D. Ground Touchdown / Landing
            const landingT = meta.landingTime || durationT;
            if (this.lastTime <= landingT && t >= landingT && !this.firedEvents.has("LANDING")) {
                this.firedEvents.add("LANDING");
                this.playOneShot("landing", 0.65);
            }
        }
        this.lastTime = t;

        // --- 2. CONTINUOUS SOUND LAYERS ---
        if (!state) return;

        // A. Motor Thrust (Powered Ascent: t < burnoutT)
        const isThrusting = t < burnoutT && state.thrust > 0.05;
        if (isThrusting) {
            const maxThrust = meta.maxThrust || 28.0;
            const normalizedThrust = Math.min(1.0, state.thrust / Math.max(8.0, maxThrust * 0.7));
            // Low/medium volume realistic motor thrust rumble
            const targetMotor = 0.22 + 0.68 * normalizedThrust;
            this.setGain(this.motorGain, targetMotor, true);
        } else {
            // Cutoff / Coast / Descent: Motor silent
            this.setGain(this.motorGain, 0, true);
        }

        // B. Airflow / Wind Ambience
        const isDescent = t >= deployT && t < durationT && state.alt > 0.05;
        const isCoast = t >= burnoutT && t < deployT;

        if (isDescent) {
            // Subtle descent airflow responding to descent rate and wind velocity
            const airSpeed = Math.abs(state.vertVel || 0) + (state.windVel || 0) * 0.35;
            // Weak wind = barely audible (0.04), stronger wind = slightly more pronounced (0.24 max)
            const targetWind = Math.min(0.24, 0.035 + (airSpeed / 12.0) * 0.16);
            this.setGain(this.windGain, targetWind, true);
        } else if (isCoast) {
            // Faint high-speed coast airflow whisper
            const coastSpeed = Math.min(0.10, (state.totalVel || 0) * 0.0015);
            this.setGain(this.windGain, coastSpeed, true);
        } else {
            // On pad or landed: silent
            this.setGain(this.windGain, 0, false);
        }
    }
}


/**
 * OpenRocket UI & Playback Controller
 * Handles HUD telemetry, timeline scrubber, event navigation,
 * playback speed, camera modes, and drag-and-drop CSV import.
 */

class UIController {
    constructor(visualizer, parser, onFileLoad, audioManager = null) {
        this.vis = visualizer;
        this.parser = parser;
        this.onFileLoad = onFileLoad;
        this.audio = audioManager;

        // Playback state
        this.currentTime = 0;
        this.isPlaying = false;
        this.speed = 1.0;
        this.isLooping = false;
        this.lastFrameTimestamp = performance.now();

        // Cached DOM elements
        this.dom = {
            title: document.getElementById("sim-title"),
            simDurationText: document.getElementById("sim-duration-text"),
            phaseBadge: document.getElementById("phase-badge"),
            eventToast: document.getElementById("event-toast"),
            
            // Simulation Data Indicators
            altVal: document.getElementById("tel-alt"),
            maxAltVal: document.getElementById("tel-max-alt"),
            vertVelVal: document.getElementById("tel-vert-vel"),
            totalVelVal: document.getElementById("tel-total-vel"),
            vertAccVal: document.getElementById("tel-vert-acc"),
            gForceVal: document.getElementById("tel-gforce"),
            thrustVal: document.getElementById("tel-thrust"),
            dragVal: document.getElementById("tel-drag"),
            timeVal: document.getElementById("tel-time"),
            driftVal: document.getElementById("tel-drift"),
            machVal: document.getElementById("tel-mach"),

            // Playback & Timeline
            playBtn: document.getElementById("btn-play"),
            playIcon: document.getElementById("play-icon"),
            pauseIcon: document.getElementById("pause-icon"),
            stepPrevBtn: document.getElementById("btn-step-prev"),
            stepNextBtn: document.getElementById("btn-step-next"),
            resetBtn: document.getElementById("btn-reset"),
            scrubber: document.getElementById("timeline-scrubber"),
            progressBar: document.getElementById("timeline-progress"),
            milestonesContainer: document.getElementById("timeline-milestones"),
            markerDotsContainer: document.getElementById("timeline-marker-dots"),
            timeDisplay: document.getElementById("playback-time-display"),
            timelinePhaseText: document.getElementById("timeline-phase-text"),
            phaseDot: document.getElementById("phase-dot"),
            speedSelect: document.getElementById("speed-select"),
            loopBtn: document.getElementById("btn-loop"),

            // Audio Controls
            soundBtn: document.getElementById("btn-sound"),
            soundVolumeSlider: document.getElementById("sound-volume-slider"),
            soundIconOn: document.getElementById("sound-icon-on"),
            soundIconOff: document.getElementById("sound-icon-off"),

            // Camera buttons
            camBtns: document.querySelectorAll("[data-cam]"),

            // Import & Notifications
            fileInput: document.getElementById("csv-file-input"),
            importBtn: document.getElementById("btn-import-csv"),
            dropOverlay: document.getElementById("drop-overlay"),
            eventJumpList: document.getElementById("event-jump-list"),
            eventCountBadge: document.getElementById("event-count-badge"),
            notification: document.getElementById("import-notification"),
            notificationText: document.getElementById("notification-text"),
            presetSelect: document.getElementById("preset-select"),

            // Environment & Ground Controls
            toggleMapBtn: document.getElementById("btn-toggle-map"),
            toggleFieldBtn: document.getElementById("btn-toggle-field"),
            toggleGridBtn: document.getElementById("btn-toggle-grid"),

            // Panel controls
            togglePanelBtn: document.getElementById("btn-toggle-panel"),
            simPanel: document.getElementById("simulation-panel")
        };

        this.notificationTimeout = null;

        if (this.audio) {
            this.audio.initUI(
                this.dom.soundBtn,
                this.dom.soundVolumeSlider,
                this.dom.soundIconOn,
                this.dom.soundIconOff
            );
            this.audio.setFlightData(this.parser);
        }

        this.initEvents();
    }

    initEvents() {
        // Satellite Map & Environment Controls
        if (this.dom.toggleMapBtn) {
            this.dom.toggleMapBtn.addEventListener("click", () => {
                const isSat = !this.vis.isSatelliteMap;
                this.vis.setSatelliteMap(isSat);
                this.dom.toggleMapBtn.innerHTML = (isSat ? "Map: Satellite" : "Map: Dark Floor") + ' <span class="arrow-down">▾</span>';
                this.dom.toggleMapBtn.classList.toggle("active", isSat);
                const viewLabel = document.getElementById("view-mode-label");
                if (viewLabel) viewLabel.textContent = isSat ? "Satellite View" : "Floor View";
                this.showNotification(isSat ? "Freestone Park Aerial Imagery Enabled" : "Dark Telemetry Floor Enabled");
            });
        }

        if (this.dom.toggleFieldBtn) {
            this.dom.toggleFieldBtn.addEventListener("click", () => {
                const nextField = (this.vis.activeLaunchField === 'parallel') ? 'west' : 'parallel';
                this.vis.setLaunchField(nextField);
                this.dom.toggleFieldBtn.innerHTML = ((nextField === 'parallel') ? "Field: Parallel" : "Field: West") + ' <span class="arrow-down">▾</span>';
                this.showNotification((nextField === 'parallel')
                    ? "Launch Site: Soccer Field (Parallel to Parking Lot)"
                    : "Launch Site: Soccer Field (West / Perpendicular)");
            });
        }

        if (this.dom.toggleGridBtn) {
            let gridVisible = true;
            this.dom.toggleGridBtn.addEventListener("click", () => {
                gridVisible = !gridVisible;
                this.vis.setGridVisible(gridVisible);
                this.dom.toggleGridBtn.innerHTML = (gridVisible ? "Grid: On" : "Grid: Off") + ' <span class="arrow-down">▾</span>';
                this.dom.toggleGridBtn.classList.toggle("active", gridVisible);
            });
        }

        // Play / Pause
        if (this.dom.playBtn) {
            this.dom.playBtn.addEventListener("click", () => this.togglePlay());
        }
        if (this.dom.resetBtn) {
            this.dom.resetBtn.addEventListener("click", () => this.resetPlayback());
        }

        // Step Previous & Next Buttons
        if (this.dom.stepPrevBtn) {
            this.dom.stepPrevBtn.addEventListener("click", () => this.stepEvent(-1));
        }
        if (this.dom.stepNextBtn) {
            this.dom.stepNextBtn.addEventListener("click", () => this.stepEvent(1));
        }

        // Simulation Panel Collapse / Expand
        if (this.dom.togglePanelBtn && this.dom.simPanel) {
            let isCollapsed = false;
            this.dom.togglePanelBtn.addEventListener("click", () => {
                isCollapsed = !isCollapsed;
                this.dom.simPanel.style.display = isCollapsed ? "none" : "flex";
                this.dom.togglePanelBtn.textContent = isCollapsed ? "›" : "‹";
            });
        }

        // Keyboard shortcuts: Space for Play/Pause, Left/Right arrows to step, +/- to zoom
        window.addEventListener("keydown", (e) => {
            if (e.target.tagName === "INPUT" || e.target.tagName === "BUTTON" || e.target.tagName === "SELECT") return;
            if (e.code === "Space") {
                e.preventDefault();
                this.togglePlay();
            } else if (e.code === "ArrowLeft") {
                e.preventDefault();
                this.stepEvent(-1);
            } else if (e.code === "ArrowRight") {
                e.preventDefault();
                this.stepEvent(1);
            } else if (e.key === "+" || e.key === "=") {
                e.preventDefault();
                this.vis.zoomCamera(-0.15); // Zoom in
            } else if (e.key === "-" || e.key === "_") {
                e.preventDefault();
                this.vis.zoomCamera(0.20);  // Zoom out
            }
        });

        // Timeline Scrubber
        if (this.dom.scrubber) {
            this.dom.scrubber.addEventListener("input", (e) => {
                const t = parseFloat(e.target.value);
                this.seek(t);
            });
        }

        // Playback speed
        if (this.dom.speedSelect) {
            this.dom.speedSelect.addEventListener("change", (e) => {
                this.speed = parseFloat(e.target.value);
            });
        }

        // Loop toggle
        if (this.dom.loopBtn) {
            this.dom.loopBtn.addEventListener("click", () => {
                this.isLooping = !this.isLooping;
                this.dom.loopBtn.classList.toggle("active", this.isLooping);
            });
        }

        // Camera mode buttons
        this.dom.camBtns.forEach(btn => {
            btn.addEventListener("click", () => {
                this.dom.camBtns.forEach(b => b.classList.remove("active"));
                btn.classList.add("active");
                this.vis.setCameraMode(btn.dataset.cam);
            });
        });

        // File Import button & input handling
        if (this.dom.fileInput) {
            this.dom.fileInput.addEventListener("click", () => {
                this.dom.fileInput.value = "";
            });
            this.dom.fileInput.addEventListener("change", (e) => {
                const file = e.target.files && e.target.files[0];
                if (file) {
                    this.loadFile(file);
                }
            });
        }

        if (this.dom.importBtn) {
            this.dom.importBtn.addEventListener("click", () => {
                if (this.dom.fileInput) {
                    this.dom.fileInput.value = "";
                    if (this.dom.importBtn.tagName !== "LABEL") {
                        this.dom.fileInput.click();
                    }
                }
            });
        }

        // Drag and Drop
        window.addEventListener("dragover", (e) => {
            e.preventDefault();
            if (this.dom.dropOverlay) this.dom.dropOverlay.classList.add("visible");
        });

        window.addEventListener("dragleave", (e) => {
            if (e.clientX <= 0 || e.clientY <= 0 || e.clientX >= window.innerWidth || e.clientY >= window.innerHeight) {
                if (this.dom.dropOverlay) this.dom.dropOverlay.classList.remove("visible");
            }
        });

        window.addEventListener("drop", (e) => {
            e.preventDefault();
            if (this.dom.dropOverlay) this.dom.dropOverlay.classList.remove("visible");
            if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                this.loadFile(e.dataTransfer.files[0]);
            }
        });
    }

    stepEvent(direction) {
        if (!this.parser || !this.parser.events || this.parser.events.length === 0) {
            this.seek(this.currentTime + direction * 0.25);
            return;
        }

        if (direction > 0) {
            const nextEv = this.parser.events.find(e => e.time > this.currentTime + 0.08);
            if (nextEv) {
                this.seek(nextEv.time);
            } else {
                this.seek(Math.min(this.parser.meta.duration, this.currentTime + 0.25));
            }
        } else {
            const prevEvents = this.parser.events.filter(e => e.time < this.currentTime - 0.08);
            if (prevEvents.length > 0) {
                const prevEv = prevEvents[prevEvents.length - 1];
                this.seek(prevEv.time);
            } else {
                this.seek(Math.max(0, this.currentTime - 0.25));
            }
        }
    }

    loadFile(file) {
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const text = event.target.result;
            if (this.onFileLoad) {
                this.onFileLoad(text, file.name);
            }
        };
        reader.onerror = (err) => {
            alert("Error reading file: " + err);
        };
        reader.readAsText(file);
    }

    showNotification(msg) {
        if (!this.dom.notification || !this.dom.notificationText) return;
        this.dom.notificationText.textContent = msg;
        this.dom.notification.classList.add("show");
        if (this.notificationTimeout) clearTimeout(this.notificationTimeout);
        this.notificationTimeout = setTimeout(() => {
            this.dom.notification.classList.remove("show");
        }, 4000);
    }

    onDataLoaded(fileName) {
        this.currentTime = 0;
        this.lastFrameTimestamp = performance.now();
        this.isPlaying = true;
        this.updatePlayState();

        // Update clean engineering title & secondary metadata
        if (this.dom.title) {
            this.dom.title.textContent = this.parser.getCleanTitle ? this.parser.getCleanTitle(fileName) : (this.parser.meta.title || "OpenRocket Flight Simulation");
        }
        if (this.dom.simDurationText) {
            const durStr = this.parser.meta.duration ? this.parser.meta.duration.toFixed(2) : "0.00";
            this.dom.simDurationText.textContent = `${durStr} s simulated flight`;
        }

        if (this.dom.scrubber) {
            this.dom.scrubber.max = this.parser.meta.duration || 1;
            this.dom.scrubber.value = 0;
        }

        // Build Milestone labels along timeline track
        this.renderMilestones();

        // Build Vertical Event List
        this.renderEventJumpList();

        // Pre-render state at t=0
        this.updateTelemetry(0);
        this.vis.update(0);

        if (this.audio) {
            this.audio.setFlightData(this.parser);
            this.audio.onReset();
            if (this.isPlaying) this.audio.onPlay(0);
        }

        // Show prominent toast notification
        const apogee = this.parser.meta.maxAltitude ? this.parser.meta.maxAltitude.toFixed(1) + "m" : "--";
        const dur = this.parser.meta.duration ? this.parser.meta.duration.toFixed(1) + "s" : "--";
        this.showNotification(`Loaded ${fileName || "flight"}: ${this.parser.records.length} data points (Apogee: ${apogee}, Time: ${dur})`);
    }

    renderMilestones() {
        if (!this.dom.milestonesContainer) return;
        this.dom.milestonesContainer.innerHTML = "";
        if (this.dom.markerDotsContainer) this.dom.markerDotsContainer.innerHTML = "";

        const duration = this.parser.meta.duration || 1;
        const keyEvents = [];

        // Select major milestone flight phases, prioritizing APOGEE
        const desired = ["IGNITION", "LIFTOFF", "BURNOUT", "APOGEE", "EJECTION_CHARGE", "GROUND_HIT"];
        desired.forEach(p => {
            const ev = this.parser.events.find(e => {
                if (p === "IGNITION") return e.name === "IGNITION" || e.name === "LAUNCH";
                if (p === "GROUND_HIT") return e.name === "GROUND_HIT" || e.name === "SIMULATION_END";
                return e.name === p;
            });
            if (ev) {
                // If EJECTION is too close to APOGEE, skip EJECTION so APOGEE always displays
                if (p === "EJECTION_CHARGE" && keyEvents.some(k => k.name === "APOGEE" && Math.abs(k.time - ev.time) < 1.0)) {
                    return;
                }
                if (!keyEvents.some(k => Math.abs(k.time - ev.time) < 0.25)) {
                    keyEvents.push(ev);
                }
            }
        });

        // Always ensure APOGEE is present
        if (!keyEvents.some(k => k.name === "APOGEE") && this.parser.meta.apogeeTime) {
            keyEvents.push({
                name: "APOGEE",
                time: this.parser.meta.apogeeTime,
                label: "Apogee Peak"
            });
        }

        // Ensure milestones are sorted chronologically
        keyEvents.sort((a, b) => a.time - b.time);

        let lastRenderedPct = -100;
        keyEvents.forEach(ev => {
            const pct = Math.min(98, Math.max(2, (ev.time / duration) * 100));

            // Small dot along the progress track for all milestones
            if (this.dom.markerDotsContainer) {
                const dot = document.createElement("div");
                dot.className = "track-milestone-dot";
                dot.style.left = `${pct}%`;
                this.dom.markerDotsContainer.appendChild(dot);
            }

            // Milestone header item above track with spacing collision avoidance
            if (pct - lastRenderedPct >= 5.5 || ev.name === "APOGEE" || ev.name.includes("GROUND")) {
                lastRenderedPct = pct;

                const item = document.createElement("div");
                item.className = "milestone-item";
                item.style.left = `${pct}%`;
                item.title = `Jump to ${ev.label} (${ev.time.toFixed(1)}s)`;

                let shortName = ev.label;
                if (ev.name.includes("IGNITION")) shortName = "Ignition";
                else if (ev.name.includes("LIFTOFF")) shortName = "Liftoff";
                else if (ev.name.includes("BURNOUT")) shortName = "Burnout";
                else if (ev.name.includes("EJECTION")) shortName = "Ejection";
                else if (ev.name.includes("APOGEE")) shortName = "Apogee";
                else if (ev.name.includes("GROUND") || ev.name.includes("END")) shortName = "Touchdown";

                item.innerHTML = `
                    <span class="milestone-name">${shortName}</span>
                    <span class="milestone-time">${ev.time.toFixed(1)}s</span>
                `;

                item.addEventListener("click", (e) => {
                    e.stopPropagation();
                    this.seek(ev.time);
                });

                this.dom.milestonesContainer.appendChild(item);
            }
        });
    }

    renderEventJumpList() {
        if (!this.dom.eventJumpList) return;
        this.dom.eventJumpList.innerHTML = "";
        if (this.dom.eventCountBadge) {
            this.dom.eventCountBadge.textContent = "SIMULATED";
        }

        this.parser.events.forEach((ev, idx) => {
            const item = document.createElement("div");
            item.className = "event-item";
            item.setAttribute("data-time", ev.time.toFixed(3));
            item.setAttribute("data-index", idx);
            item.title = `Jump to ${ev.label} (t = ${ev.time.toFixed(2)}s)`;

            item.innerHTML = `
                <span class="event-time-tag">${ev.time.toFixed(1)}s</span>
                <span class="event-marker-dot"></span>
                <span class="event-name-tag">${ev.label}</span>
            `;

            item.addEventListener("click", () => {
                this.seek(ev.time);
            });
            this.dom.eventJumpList.appendChild(item);
        });
    }

    togglePlay() {
        // If simulation reached the end and user clicks Play, restart from beginning
        if (!this.isPlaying && this.currentTime >= (this.parser.meta.duration - 0.05)) {
            this.currentTime = 0;
            this.seek(0);
            if (this.audio) this.audio.onReset();
        }
        this.isPlaying = !this.isPlaying;
        this.updatePlayState();

        if (this.audio) {
            if (this.isPlaying) {
                this.audio.onPlay(this.currentTime);
            } else {
                this.audio.onPause();
            }
        }
    }

    updatePlayState() {
        if (this.isPlaying) {
            if (this.dom.playIcon) this.dom.playIcon.style.display = "none";
            if (this.dom.pauseIcon) this.dom.pauseIcon.style.display = "block";
        } else {
            if (this.dom.playIcon) this.dom.playIcon.style.display = "block";
            if (this.dom.pauseIcon) this.dom.pauseIcon.style.display = "none";
        }
    }

    resetPlayback() {
        this.currentTime = 0;
        this.seek(0);
        this.isPlaying = true;
        this.updatePlayState();
        if (this.audio) {
            this.audio.onReset();
            this.audio.onPlay(0);
        }
    }

    seek(time) {
        this.currentTime = Math.max(0, Math.min(time, this.parser.meta.duration));
        if (this.dom.scrubber) this.dom.scrubber.value = this.currentTime;
        this.updateTelemetry(this.currentTime);
        this.vis.update(this.currentTime);
        if (this.audio) {
            this.audio.onSeek(this.currentTime, this.isPlaying);
        }
    }

    /**
     * Main animation tick
     */
    tick(now) {
        const rawDelta = (now - this.lastFrameTimestamp) / 1000;
        this.lastFrameTimestamp = now;
        // Clamp delta to prevent huge jumps when browser window was unfocused or file dialog was open
        const delta = Math.min(Math.max(0, rawDelta), 0.1);

        if (this.isPlaying && this.parser.records.length > 0) {
            this.currentTime += delta * this.speed;

            if (this.currentTime >= this.parser.meta.duration) {
                if (this.isLooping) {
                    this.currentTime = 0;
                    if (this.audio) this.audio.onReset();
                } else {
                    this.currentTime = this.parser.meta.duration;
                    this.isPlaying = false;
                    this.updatePlayState();
                    if (this.audio) this.audio.onPlaybackEnd();
                }
            }

            if (this.dom.scrubber) this.dom.scrubber.value = this.currentTime;
            this.updateTelemetry(this.currentTime);
            this.vis.update(this.currentTime);
        }

        // Synchronize flight sound effects
        if (this.audio) {
            this.audio.update(this.currentTime, this.isPlaying, this.speed);
        }

        // Render 3D scene
        this.vis.render();

        requestAnimationFrame((t) => this.tick(t));
    }

    updateTelemetry(t) {
        const state = this.parser.sample(t);
        if (!state) return;

        // Scrubber progress bar visual
        const duration = this.parser.meta.duration || 1;
        const pct = (t / duration) * 100;
        if (this.dom.progressBar) this.dom.progressBar.style.width = `${pct}%`;
        const handle = document.getElementById("timeline-handle");
        if (handle) handle.style.left = `${pct}%`;

        // Time display
        if (this.dom.timeDisplay) this.dom.timeDisplay.textContent = `${t.toFixed(2)} s / ${duration.toFixed(2)} s`;

        // Telemetry numbers
        if (this.dom.altVal) this.dom.altVal.textContent = state.alt.toFixed(1);
        if (this.dom.maxAltVal) this.dom.maxAltVal.textContent = this.parser.meta.maxAltitude.toFixed(1);
        if (this.dom.vertVelVal) this.dom.vertVelVal.textContent = (state.vertVel >= 0 ? "+" : "") + state.vertVel.toFixed(1);
        if (this.dom.totalVelVal) this.dom.totalVelVal.textContent = state.totalVel.toFixed(1);
        if (this.dom.vertAccVal) this.dom.vertAccVal.textContent = state.vertAcc.toFixed(1);
        if (this.dom.gForceVal) this.dom.gForceVal.textContent = (state.totalAcc / 9.80665).toFixed(1);
        if (this.dom.thrustVal) this.dom.thrustVal.textContent = state.thrust.toFixed(1);
        if (this.dom.dragVal) this.dom.dragVal.textContent = state.drag.toFixed(2);
        if (this.dom.timeVal) this.dom.timeVal.textContent = t.toFixed(2);
        if (this.dom.driftVal) this.dom.driftVal.textContent = state.lateralDist.toFixed(1);
        if (this.dom.machVal) this.dom.machVal.textContent = state.mach.toFixed(2);

        // Flight Phase Badge & Timeline Phase Display
        const phase = this.parser.getFlightPhase(t);
        if (this.dom.timelinePhaseText) {
            this.dom.timelinePhaseText.textContent = phase.name;
            this.dom.timelinePhaseText.style.color = phase.color;
        }
        if (this.dom.phaseDot) {
            this.dom.phaseDot.style.color = phase.color;
        }

        // Highlight active / past / upcoming events in the flight event list
        if (this.dom.eventJumpList) {
            const items = this.dom.eventJumpList.querySelectorAll(".event-item");
            let activeIdx = -1;
            this.parser.events.forEach((ev, idx) => {
                if (ev.time <= t + 0.15) {
                    activeIdx = idx;
                }
            });

            items.forEach((el, idx) => {
                const evTime = parseFloat(el.getAttribute("data-time"));
                el.classList.remove("active", "passed", "upcoming");
                if (idx === activeIdx) {
                    el.classList.add("active");
                } else if (evTime < t) {
                    el.classList.add("passed");
                } else {
                    el.classList.add("upcoming");
                }
            });
        }
    }
}


/**
 * Application Entry Point
 * Orchestrates Parser, 3D Visualizer, and UI Controller.
 */

document.addEventListener("DOMContentLoaded", () => {
    const container = document.getElementById("canvas-container");
    const visualizer = new RocketVisualizer(container);
    const audioManager = new FlightAudioManager();
    const parser = new OpenRocketParser();

    // Callback when user drags or imports a new CSV
    const handleNewFlightData = (csvText, fileName) => {
        try {
            parser.parse(csvText);
            if (!parser.records || parser.records.length === 0) {
                throw new Error("No flight data points could be found in the file. Please ensure it is an OpenRocket export containing Time and Altitude.");
            }
            visualizer.loadTrajectory(parser);
            ui.onDataLoaded(fileName);

            // Update preset selector to show the active file
            const presetSelect = document.getElementById("preset-select");
            if (presetSelect) {
                if (fileName === "sim1.csv" || fileName === "D12-3 Default") {
                    presetSelect.value = "default";
                } else if (fileName === "sim1 (F32T 87s)") {
                    presetSelect.value = "sim1";
                } else if (fileName === "f32t no angle.csv") {
                    presetSelect.value = "f32t";
                } else {
                    let customOpt = presetSelect.querySelector("option[data-custom='true']");
                    if (!customOpt) {
                        customOpt = document.createElement("option");
                        customOpt.setAttribute("data-custom", "true");
                        presetSelect.appendChild(customOpt);
                    }
                    customOpt.value = "custom";
                    customOpt.textContent = fileName;
                    presetSelect.value = "custom";
                }
            }

            console.log(`Loaded flight: ${fileName || parser.meta.title} (${parser.records.length} data points)`);
        } catch (err) {
            console.error("Failed to parse OpenRocket CSV:", err);
            alert("Error importing flight data:\n" + err.message);
        }
    };

    const ui = new UIController(visualizer, parser, handleNewFlightData, audioManager);
    window.visualizer = visualizer;
    window.audioManager = audioManager;
    window.ui = ui;
    window.parser = parser;

    // Preset dropdown handler
    const presetSelect = document.getElementById("preset-select");
    if (presetSelect) {
        presetSelect.addEventListener("change", (e) => {
            if (e.target.value === "default") {
                handleNewFlightData(DEFAULT_FLIGHT_CSV, "sim1.csv");
            } else if (e.target.value === "sim1") {
                handleNewFlightData(SIM1_CSV, "sim1 (F32T 87s)");
            } else if (e.target.value === "f32t") {
                handleNewFlightData(F32T_CSV, "f32t no angle.csv");
            }
        });
    }

    // Default load D12-3 flight simulation as sim1.csv (matching reference UI)
    handleNewFlightData(DEFAULT_FLIGHT_CSV, "sim1.csv");

    // Start 60fps render loop
    requestAnimationFrame((t) => ui.tick(t));
});

